(function(){var m=window.SITE_DATA_BY_DOMAIN||{};var d=m["coding"]||{};var a=d["papers"]||[];for(var i=0;i<a.length;i++){if(a[i].id=="paper-fastcoder-accelerating-repository-le-2025"){a[i]["long_html"]="<nav class=\"long-toc\"><b>本页目录</b><ol><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-fastcoder-accelerating-repository-le-2025-sec-1\">一 · 现场：一次仓库级补全请求在推理栈里撞上的三堵墙</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-fastcoder-accelerating-repository-le-2025-sec-2\">二 · 旧方案的检索形态：一次性召回、无预算约束、与生成脱钩</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-fastcoder-accelerating-repository-le-2025-sec-3\">三 · 为什么非改不可：SLO 与成本结构同时失效</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-fastcoder-accelerating-repository-le-2025-sec-4\">四 · 在线补全服务里，全量拼接与“检索+验证”各自的失效边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-fastcoder-accelerating-repository-le-2025-sec-5\">五 · 请求到达的形态：签名、路径与仓库快照三元组</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-fastcoder-accelerating-repository-le-2025-sec-6\">六 · 输入长度分布：被截断而非被拼接</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-fastcoder-accelerating-repository-le-2025-sec-7\">七 · 并发与批大小：多候选放大解码开销</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-fastcoder-accelerating-repository-le-2025-sec-8\">八 · SLO 与长尾：验证时间计入端到端</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-fastcoder-accelerating-repository-le-2025-sec-9\">九 · 负载塑造方案，方案反向限制负载</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-fastcoder-accelerating-repository-le-2025-sec-10\">十 · 可核查的测量清单</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-fastcoder-accelerating-repository-le-2025-sec-11\">十一 · 请求形态如何反向约束检索预算与验证并发</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-fastcoder-accelerating-repository-le-2025-sec-12\">十二 · 从 B_ctx 到 kernel 选择：预填规模如何决定精度档位</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-fastcoder-accelerating-repository-le-2025-sec-13\">十三 · FP16/BF16/FP8/NVFP4：四种格式在代码模型上的取舍</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-fastcoder-accelerating-repository-le-2025-sec-14\">十四 · 累加精度：FP32 累加器与分块归约的误差账</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-fastcoder-accelerating-repository-le-2025-sec-15\">十五 · tcgen05 与 TMEM：把累加器搬进张量内存</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-fastcoder-accelerating-repository-le-2025-sec-16\">十六 · 2-SM MMA：跨 SM 协作与通信代价</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-fastcoder-accelerating-repository-le-2025-sec-17\">十七 · 精度与验证环节的耦合：误差预算怎么定</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-fastcoder-accelerating-repository-le-2025-sec-18\">十八 · 检索预算与验证开销夹击下的数值精度边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-fastcoder-accelerating-repository-le-2025-sec-19\">十九 · 显存账本的三本账：权重、激活、KV</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-fastcoder-accelerating-repository-le-2025-sec-20\">二十 · 分页与复用：把 KV 从连续块变成可调度资源</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-fastcoder-accelerating-repository-le-2025-sec-21\">二十一 · 压缩与卸载：结构压缩、量化与分层放置</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-fastcoder-accelerating-repository-le-2025-sec-22\">二十二 · 一个可复算的显存预算</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-fastcoder-accelerating-repository-le-2025-sec-23\">二十三 · 带宽瓶颈的位置与验证环节的显存代价</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-fastcoder-accelerating-repository-le-2025-sec-24\">二十四 · 工程判断：预算先于压缩，复用先于卸载</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-fastcoder-accelerating-repository-le-2025-sec-25\">二十五 · 预算封顶后的显存账本与失效边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-fastcoder-accelerating-repository-le-2025-sec-26\">二十六 · 从“三段流水线”到“可调度队列”：请求形态决定批处理结构</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-fastcoder-accelerating-repository-le-2025-sec-27\">二十七 · 连续批处理与 chunked prefill：把 B_ctx 变成可切分的预填预算</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-fastcoder-accelerating-repository-le-2025-sec-28\">二十八 · 优先级与抢占：验证通过率作为调度信号</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-fastcoder-accelerating-repository-le-2025-sec-29\">二十九 · 分离式预填/解码：把预填的算力密集与解码的带宽密集拆开</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-fastcoder-accelerating-repository-le-2025-sec-30\">三十 · 尾延迟怎么压：验证异步化、候选配额与缓存版本校验</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-fastcoder-accelerating-repository-le-2025-sec-31\">三十一 · 切分维度：检索流水线里谁在并行</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-fastcoder-accelerating-repository-le-2025-sec-32\">三十二 · NVLink 5 与 NVSwitch：域内带宽决定 TP 上限</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-fastcoder-accelerating-repository-le-2025-sec-33\">三十三 · All-to-All 与 All-Reduce：EP 的代价在哪</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-fastcoder-accelerating-repository-le-2025-sec-34\">三十四 · PP 与 DP：流水线气泡与副本收益</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-fastcoder-accelerating-repository-le-2025-sec-35\">三十五 · NIXL 传输：段间搬运的隐藏延迟</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-fastcoder-accelerating-repository-le-2025-sec-36\">三十六 · 通信何时成为瓶颈：三个判据</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-fastcoder-accelerating-repository-le-2025-sec-37\">三十七 · 并行切分与通信：检索流水线的边界在哪里</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-fastcoder-accelerating-repository-le-2025-sec-38\">三十八 · 精度塌陷：从“能跑”到“跑错”的隐性路径</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-fastcoder-accelerating-repository-le-2025-sec-39\">三十九 · OOM 与批抖动：显存账本的两条泄漏路径</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-fastcoder-accelerating-repository-le-2025-sec-40\">四十 · 尾延迟：验证环节是长尾的主要贡献者</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-fastcoder-accelerating-repository-le-2025-sec-41\">四十一 · 静默降级：验证覆盖不全与缓存过期</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-fastcoder-accelerating-repository-le-2025-sec-42\">四十二 · 定位与回滚：把失败模式映射到可回退的开关</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-fastcoder-accelerating-repository-le-2025-sec-43\">四十三 · 口径先于数字：这篇论文的“可读区”与“不可读区”</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-fastcoder-accelerating-repository-le-2025-sec-44\">四十四 · 硬件档位与 batch/并发：材料留白处的推理系统代价</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-fastcoder-accelerating-repository-le-2025-sec-45\">四十五 · 指标怎么读：TTFT、TPOT、吞吐、显存、功耗的归因链</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-fastcoder-accelerating-repository-le-2025-sec-46\">四十六 · 哪些提升不可比：四类典型的伪对比</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-fastcoder-accelerating-repository-le-2025-sec-47\">四十七 · 前缀缓存与仓库快照：口径里最容易被忽略的变量</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-fastcoder-accelerating-repository-le-2025-sec-48\">四十八 · 落到可执行的读法：把论文当口径模板而非成绩单</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-fastcoder-accelerating-repository-le-2025-sec-49\">四十九 · 基准口径与不可比边界：把 B_ctx、候选数与验证耗时放进同一张账</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-fastcoder-accelerating-repository-le-2025-sec-50\">五十 · 迁移到非代码领域：检索器的语义退化与验证器的消失</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-fastcoder-accelerating-repository-le-2025-sec-51\">五十一 · 迁到别的代码模型：解码机制不变，但候选数与验证吞吐的匹配要重算</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-fastcoder-accelerating-repository-le-2025-sec-52\">五十二 · 与 Blackwell 部署机制的衔接：前缀缓存是唯一可直接复用的杠杆</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-fastcoder-accelerating-repository-le-2025-sec-53\">五十三 · 规模上限：检索质量与验证覆盖率决定天花板，而非上下文预算</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-fastcoder-accelerating-repository-le-2025-sec-54\">五十四 · 不适用的场景与判断边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-fastcoder-accelerating-repository-le-2025-sec-55\">五十五 · 迁移与边界：检索-验证流水线的适用条件与失效面</button></li></ol></nav><figure class=\"diagram\" data-fig=\"paper-pipeline\"><svg style=\"max-width:590px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 590.0 423\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><rect x=\"58.0\" y=\"12.0\" width=\"508.0\" height=\"44.8\" rx=\"8\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"34.4\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"38.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">1</text><text x=\"75.0\" y=\"39.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">请求进入：接收目标函数签名、文件路径与仓库快照，确定检索查询与上下文预…</text><line x1=\"82.0\" y1=\"58.8\" x2=\"82.0\" y2=\"75.8\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 74.8 L 86.5 74.8 L 82.0 82.8 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"82.8\" width=\"508.0\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"105.3\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"109.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">2</text><text x=\"75.0\" y=\"110.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">仓库检索：在仓库索引上召回相关文件与符号片段，按相关性排序并截断到预算…</text><line x1=\"82.0\" y1=\"129.7\" x2=\"82.0\" y2=\"146.7\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 145.7 L 86.5 145.7 L 82.0 153.7 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"153.7\" width=\"508.0\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"176.1\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"180.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">3</text><text x=\"75.0\" y=\"181.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">上下文组装：把片段按依赖顺序拼接为提示，控制预填 token 总量以约…</text><line x1=\"82.0\" y1=\"200.5\" x2=\"82.0\" y2=\"217.5\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 216.5 L 86.5 216.5 L 82.0 224.5 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"224.5\" width=\"508.0\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"247.0\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"251.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">4</text><text x=\"75.0\" y=\"252.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">候选生成：模型在组装上下文下解码出若干代码候选，受解码长度与批调度约束。</text><line x1=\"82.0\" y1=\"271.4\" x2=\"82.0\" y2=\"288.4\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 287.4 L 86.5 287.4 L 82.0 295.4 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"295.4\" width=\"508.0\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"317.8\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"322.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">5</text><text x=\"75.0\" y=\"323.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">验证过滤：对候选执行编译与测试，丢弃失败候选，保留通过验证者返回。</text><line x1=\"82.0\" y1=\"342.2\" x2=\"82.0\" y2=\"359.2\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 358.2 L 86.5 358.2 L 82.0 366.2 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"366.2\" width=\"508.0\" height=\"44.8\" rx=\"8\" fill=\"#e8f5ec\" stroke=\"#cde9d5\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"388.7\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"392.9\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">6</text><text x=\"75.0\" y=\"393.9\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">回写与缓存：把通过的片段与验证结果记入前缀缓存，供后续同仓库请求复用。</text></svg><figcaption><b>流水线</b> · 从输入到输出的数据流；每一步的模块与代价在正文展开。</figcaption></figure>\n<h3 id=\"paper-fastcoder-accelerating-repository-le-2025-sec-1\">一 · 现场：一次仓库级补全请求在推理栈里撞上的三堵墙</h3>\n<p>设想一个在线代码服务平台：IDE 插件把光标处的目标函数签名、当前文件路径与仓库快照一起发到后端，用户在等一个可编译的实现。请求到达时，推理栈要做的事远不止“调一次模型”。它必须先决定给模型看什么——而这个仓库可能有数千个文件、数十万行代码，跨文件的类型定义、工具函数、接口约定散落在各处。旧方案的主流做法是把问题当成一个长上下文问题：尽量多塞，塞到上下文窗口为止。这条路在仓库级场景下立刻撞上三堵墙。</p>\n<p>第一堵墙是预填预算。全量拼接意味着预填 token 规模随仓库规模线性膨胀，而预填充阶段的计算量与 KV cache 占用都正比于输入长度。对解码阶段的注意力而言，KV cache 的显存占用可写成</p>\n<div class=\"formula\">$$M_{\\mathrm{KV}} \\approx 2 \\cdot L \\cdot H_{\\mathrm{kv}} \\cdot d_{\\mathrm{head}} \\cdot s \\cdot b \\cdot \\mathrm{bytes}$$</div>\n<p>其中 $L$ 为层数、$H_{\\mathrm{kv}}$ 为 KV 头数、$s$ 为序列长度、$b$ 为并发批大小。序列长度 $s$ 一旦被仓库规模顶到窗口上限，$M_{\\mathrm{KV}}$ 就随并发数迅速吃掉显存，批大小被迫压到很小，吞吐随之塌陷；同时首 token 延迟（TTFT）由一次超长预填主导，用户在编辑器里等的是秒级而非毫秒级响应。第二堵墙是上下文窗口本身：即使窗口足够大，把整仓库塞进去也意味着模型要在大量无关代码中定位相关符号，注意力被稀释，生成质量并不随上下文长度单调上升。第三堵墙是正确性：仓库级生成的输出必须能编译、能过测试，而旧栈只做概率采样，没有任何执行层面的筛选，错误候选直接返回给用户，下游返工的成本被推给了调用方。</p>\n<p>具体到一个例子：目标函数要调用同仓库另一个模块里的 `parse_config`，其定义在三个目录之外的一个工具文件中。全量拼接方案要么因为窗口截断恰好丢掉那个文件，要么把它塞进去但付出整仓预填的代价；无论哪种，端到端延迟和显存都被这一个请求拖住。旧栈的痛点不是单点的，而是预填、显存、正确性三者互相锁死：想提高质量就加长上下文，加长上下文就抬高预填与 KV 成本，成本抬高就压低并发与 SLO，而质量本身还没有任何执行验证兜底。</p>\n\n<h3 id=\"paper-fastcoder-accelerating-repository-le-2025-sec-2\">二 · 旧方案的检索形态：一次性召回、无预算约束、与生成脱钩</h3>\n<p>在 FastCoder 之前，工程上并非没有检索。常见的做法是“先检索再生成”的两段式：用目标签名或文件路径做查询，从仓库索引里召回若干片段，拼进提示，然后一次性解码。问题出在三个环节的耦合方式上。其一是召回没有预算概念：检索器按相关性返回一个固定 top-k，组装器把结果原样拼接，上下文长度由 k 和片段长度被动决定，而不是由预填预算主动约束。其二是召回信号单薄：仅以文本相似度或签名匹配排序，跨文件的定义—调用关系、类型依赖这些结构性信号没有被显式建模，导致“相关”的片段未必是“编译所必需”的片段。其三是检索与生成之间没有反馈回路：检索一次定终身，生成阶段发现缺符号也无从补救，只能整条请求失败或返回不可编译的代码。</p>\n<p>这套形态的推理系统代价可以直接算出来。设召回片段平均长度为 $\\ell$、召回数为 $k$，则预填 token 规模约为 $k\\ell$，与仓库真实规模脱钩但与 $k$ 强相关；工程上为了“保险”往往把 $k$ 调大，于是预填成本、KV 占用、TTFT 一起上升，而召回精度并未同比例提升。更麻烦的是，这种两段式把检索开销放在请求的关键路径上：索引查询、片段读取、拼接都要在预填之前完成，任何一步的尾延迟都会叠加到 TTFT 上。对于低延迟代码补全这类 SLO 以百毫秒计的场景，这条路径的固定开销已经吃掉了大部分预算。</p>\n<p>表格对比一下旧栈两种典型形态的代价结构：</p>\n<table class=\"mini\"><thead><tr><th>形态</th><th>上下文规模</th><th>KV/预填代价</th><th>正确性保障</th><th>关键路径风险</th></tr></thead><tbody><tr><td>全量拼接</td><td>随仓库规模膨胀，顶到窗口上限</td><td>预填与 KV 随序列长度线性上升，批大小被压缩</td><td>无，纯概率采样</td><td>TTFT 由超长预填主导</td></tr><tr><td>固定 top-k 检索</td><td>由 k 与片段长度被动决定</td><td>与 k 强相关，k 调大即成本上升</td><td>无，检索错则生成错</td><td>检索、读取、拼接串行叠加在预填前</td></tr></tbody></table>\n<p>值得注意的是，旧栈还有一个隐性代价：重复预填。同一仓库的多个请求往往共享大量相同片段，但两段式每次请求都从头检索、从头预填，前缀缓存即便存在也没有和检索结果绑定，缓存命中率低。这在仓库级服务里是纯粹的浪费——同一个工具文件的定义被反复编码进 KV，却每次都要重付预填的算力与延迟。</p>\n\n<h3 id=\"paper-fastcoder-accelerating-repository-le-2025-sec-3\">三 · 为什么非改不可：SLO 与成本结构同时失效</h3>\n<p>把问题放到在线服务的容量视角下，旧栈的失效是结构性的，不是调参能救的。仓库级请求的端到端延迟可以拆成</p>\n<div class=\"formula\">$$T_{\\mathrm{e2e}} = T_{\\mathrm{retrieve}} + T_{\\mathrm{prefill}}(s) + T_{\\mathrm{decode}}(n) + T_{\\mathrm{verify}}$$</div>\n<p>旧栈里 $T_{\\mathrm{prefill}}(s)$ 中的 $s$ 不受控，$T_{\\mathrm{verify}}$ 项根本不存在（没有验证环节），于是延迟的方差极大：小请求快、大仓库请求慢，容量规划只能按最坏情况留余量，GPU 利用率被拉低。吞吐侧同样如此，KV cache 被长序列占满后，连续批处理能容纳的并发请求数下降，单位显存产出的 token 数变差。换句话说，旧栈把成本重心压在“预填超长上下文”上，而这个成本既不随请求难度变化，也不产生正确性收益。</p>\n<p>一个具体的工程判断：当仓库规模超过某个阈值，全量拼接方案的预填预算已经无法与低延迟补全的 SLO 共存——不是慢一点的问题，而是批大小被压到无法维持服务吞吐。此时唯一的出路是把长上下文问题转化成别的问题。FastCoder 的选择是把仓库压缩成受预算 $B_{\\mathrm{ctx}}$ 约束的检索片段，并用编译与测试验证候选，把成本重心从预填转移到检索与验证。这个转向的直接后果是：预填 token 规模由 $B_{\\mathrm{ctx}}$ 主动约束而非由仓库规模被动决定，KV cache 占用与 TTFT 因此可被容量规划；验证环节虽然引入额外执行开销，但它替代了“错误候选返回后下游返工”的隐性成本，把正确性从概率问题变成可执行筛选的问题。</p>\n<p>代价也必须说清楚：验证执行时间计入端到端延迟，多候选生成会线性放大解码开销，检索召回不足会丢失跨文件符号。这些是 FastCoder 流水线自带的张力，也是后续部分要展开的工程细节。就本部分而言，结论落在机制上：旧栈的失效源于预填规模不受控且正确性无兜底，任何在 Blackwell 上服务仓库级请求的推理栈，都必须先把上下文预算变成显式参数、把验证变成流水线的一等环节，否则显存与 SLO 无法同时守住。</p>\n\n<h3 id=\"paper-fastcoder-accelerating-repository-le-2025-sec-4\">四 · 在线补全服务里，全量拼接与“检索+验证”各自的失效边界</h3>\n\n<p>设想一个托管在 GB200 NVL72 上的仓库级代码补全服务：IDE 插件在用户敲下函数签名后 300 毫秒内要拿到可编译的补全，请求携带目标签名、当前文件路径与仓库快照。旧方案的主流做法是把目标文件、同目录文件、被 import 的头文件按启发式顺序拼接成一个超长提示，直接送进代码模型预填。问题在于仓库级上下文远超单次可承受的预填预算：预填 token 随拼接文件数线性增长，KV cache 占用随上下文长度与并发批大小相乘膨胀，首 token 延迟被预填主导。在连续批处理下，一个长上下文请求会挤占同一批次里其余短请求的显存配额，把整批的 token 间延迟一起拖高——这是典型的队头阻塞，吞吐与尾延迟同时受损。更麻烦的是，拼接顺序是静态启发式，跨文件的定义与调用关系经常被截断在窗口之外，模型看到的是残缺符号表，生成结果编译不过，下游返工又把成本推回服务端。</p>\n\n<p>FastCoder 的切入点是把长上下文问题转化为检索与验证问题，其上下文组装受预算约束：<div class=\"formula\">$$\\mathrm{ctx}=\\mathrm{TopK}\\big(\\mathrm{score}(q,\\,d_i)\\big),\\quad |\\mathrm{ctx}|\\le B_{\\mathrm{ctx}}$$</div>检索器以目标签名与文件路径为查询召回文件与符号片段，组装器按依赖顺序拼接并截断到 B_ctx，预填规模因此受控而非随仓库规模膨胀。但这条路径有自己的边界。第一，B_ctx 若被当作固定常量，小仓库会浪费预算、大仓库会丢关键符号；召回不足时跨文件定义与调用关系缺失，模型生成的是“看起来对但引用不存在符号”的代码，这类失败不会在编译前暴露。第二，生成侧一次产出多个候选，多候选线性放大解码开销，必须与验证吞吐匹配，否则解码排队先于验证排队成为瓶颈。第三，验证器执行编译与测试，执行时间计入端到端延迟；在低延迟补全场景里，验证环节可能吃掉整个 SLO 预算，尤其当测试用例需要拉起依赖环境时。第四，前缀缓存复用检索片段时若不校验仓库快照版本，仓库变更后会复用过期上下文，生成引用已删除符号——这是静默失败，验证器若覆盖不全则漏过。</p>\n\n<table class=\"mini\"><thead><tr><th>环节</th><th>主要系统代价</th><th>失效条件</th></tr></thead><tbody><tr><td>全量拼接预填</td><td>KV cache 随上下文与批大小膨胀，首 token 延迟升高，批内队头阻塞</td><td>仓库规模超过预填预算，静态拼接顺序截断跨文件依赖</td></tr><tr><td>检索+组装</td><td>检索本身有索引查询开销，B_ctx 约束预填规模</td><td>召回不足丢符号；B_ctx 固定不随仓库与请求类型调整</td></tr><tr><td>多候选生成</td><td>解码开销随候选数线性放大</td><td>候选数与验证吞吐不匹配，解码排队成为瓶颈</td></tr><tr><td>编译与测试验证</td><td>执行时间计入端到端延迟</td><td>验证覆盖不全漏过错误候选；测试环境拉起拖垮 SLO</td></tr></tbody></table>\n\n<p>所以“非改不可”的理由不是全量拼接一定更慢，而是它的代价结构不可控：预填成本由仓库规模决定，而服务 SLO 由最慢的那个请求决定。检索加验证把成本重心从预填转移到检索质量与验证吞吐，代价变得可预算——B_ctx 约束 KV cache，候选数约束解码，验证覆盖率约束漏过率。但这条流水线并未消除长上下文压力，只是把它换成了三个可观测的量：召回率、验证通过率、端到端延迟。工程判断在于，这三个量必须联合调参而不能各自最优：把 B_ctx 压到极小换预填延迟，召回率下降会让验证通过率崩塌，多候选与重试又把解码开销推回去；把验证做全换正确率，执行延迟直接顶穿低延迟补全的 SLO。真正决定部署形态的是请求类型分层——交互式补全走短预算、单候选、轻量语法检查，批式仓库迁移走大预算、多候选、完整测试验证，两套 SLO 不能共用同一个 B_ctx 常量。</p>\n<h3 id=\"paper-fastcoder-accelerating-repository-le-2025-sec-5\">五 · 请求到达的形态：签名、路径与仓库快照三元组</h3>\n<p>仓库级代码生成请求的输入不是一段自然语言，而是三元组：目标函数签名、文件路径、仓库快照。这三者共同决定检索查询的构造方式与上下文预算的分配。签名给出符号名与参数类型，路径给出该符号在仓库中的位置与同目录邻居，快照版本决定索引是否与当前代码一致。工程上必须把这三项作为请求元数据随请求一起落盘，否则后续无法复现检索结果，也无法判断前缀缓存是否过期。</p>\n<p>测量口径上，请求形态要按“签名长度、路径深度、同目录文件数、跨文件引用数”四个维度分桶统计。跨文件引用数是关键：它近似等于检索需要覆盖的符号边数，直接决定 B_ctx 是否够用。一个只调用同文件内两个辅助函数的请求，与一个横跨三个包、引用五个基类方法的请求，在检索召回难度上不在同一量级，但二者在请求队列里看起来同样轻。若不按引用数分桶，延迟长尾会被平均掉，容量规划就会失真。</p>\n<p>代价落在预填侧：上下文组装把片段按依赖顺序拼接，预填 token 规模随 B_ctx 线性受控，而 B_ctx 的取值必须由引用数分桶驱动，而非全局常量。固定常量在小仓库浪费预算、在大仓库丢符号，这是材料明确列出的失败模式。可核查的做法是记录每个请求的“引用数—实际召回片段数—被截断片段数”三元组，截断数为正即说明预算不足，这是可量化的预算告警信号。</p>\n\n<h3 id=\"paper-fastcoder-accelerating-repository-le-2025-sec-6\">六 · 输入长度分布：被截断而非被拼接</h3>\n<p>本方案的输入长度分布不是由仓库规模决定的，而是由检索器召回后截断到 B_ctx 决定的。这意味着长度分布的上界被人为钉死，长尾被转移到“截断损失”上：请求不会因为仓库大而变慢，但会因为关键符号被截掉而失败。测量时必须同时记录两个分布——送入模型的预填 token 长度分布，以及被截断片段的符号重要性分布。前者决定 KV cache 与首 token 延迟，后者决定一次通过率。</p>\n<p>上下文预算与 KV 占用的关系可直接写成约束：</p>\n<div class=\"formula\">$$\\mathrm{KV}_{\\text{req}} \\approx 2 \\cdot L \\cdot H_{\\text{kv}} \\cdot d_{\\text{head}} \\cdot |\\mathrm{ctx}| \\cdot b_{\\text{bytes}}$$</div>\n<p>其中 |ctx| 受 B_ctx 约束，因此单请求 KV 占用随预算线性增长，与仓库总规模无关。这条式子给出一个可核查的容量口径：并发数 N 与预算 B_ctx 的乘积决定常驻 KV 上限，调度器必须在这个乘积内做准入控制，而不是按请求数无脑放行。若把 B_ctx 当作固定常量，KV 预算就变成 N 的线性函数，长尾请求一旦扎堆就会触发换出。</p>\n<p>具体例子：同一仓库内，一个改签名的请求需要召回所有调用点，引用数高、截断风险大；一个新增工具函数的请求只需召回同目录的工具模块，引用数低、预算富余。二者共享同一 B_ctx 时，前者被截断、后者浪费，这正是按引用数分桶分配预算的直接动因。测量上应输出“按引用数分桶的截断率”曲线，截断率随分桶单调上升即说明预算分配策略失效。</p>\n\n<h3 id=\"paper-fastcoder-accelerating-repository-le-2025-sec-7\">七 · 并发与批大小：多候选放大解码开销</h3>\n<p>生成侧一次产出多个代码候选，候选数量与解码长度材料未给出，但结构上确定：多候选线性放大解码开销，而验证器是串行执行编译与测试的，二者吞吐必须匹配。若候选数为 k，解码侧的有效 token 吞吐需求约为单候选的 k 倍，验证侧的执行队列长度也约为 k 倍。批调度若只按解码吞吐做连续批处理，会把验证队列压爆，端到端延迟由验证排队主导而非解码主导。</p>\n<p>可核查的批调度思路是把候选生成与验证解耦为两级队列：解码侧按 token 预算做连续批处理，验证侧按执行槽位做准入。伪代码层面：</p>\n<ul>\n<li>解码批：每步从等待队列取请求，累计预填 token 不超过批预算，解码到候选数 k 后整批出队；</li>\n<li>验证批：候选进入执行队列，按编译与测试的槽位数并发执行，通过者回写缓存，失败者丢弃；</li>\n<li>回压：验证队列深度超过阈值时，降低解码侧新请求的准入速率，而非降低 k。</li>\n</ul>\n<p>代价口径：并发 N 与候选数 k 的乘积决定解码侧瞬时显存与验证侧执行并发。材料未给出 k 与并发，因此容量规划只能给出定性判断——k 越大，验证环节对 SLO 的拖拽越强，低延迟补全场景应把 k 压到最小可行值，把预算留给检索召回而非候选多样性。这是方案反过来限制负载的典型：验证成本迫使系统在“多采样提通过率”和“低延迟”之间做取舍。</p>\n\n<h3 id=\"paper-fastcoder-accelerating-repository-le-2025-sec-8\">八 · SLO 与长尾：验证时间计入端到端</h3>\n<p>SLO 面向一次通过率与端到端延迟，而验证执行时间计入总延迟，这是本方案与纯解码系统在 SLO 口径上的根本差异。端到端延迟可拆为四段：检索、组装预填、解码、验证。前三段随 B_ctx 与 k 线性变化，第四段随候选的编译与测试复杂度变化，且方差远大于前三段——编译失败快、测试超时慢，长尾几乎全部来自验证。</p>\n<p>因此 SLO 测量必须分段打点，而不是只报端到端 P50。可核查的口径是：为每段记录 P50/P90/P99，并对验证段单独记录“编译耗时分布”与“测试耗时分布”。若验证段 P99 显著高于解码段 P99，则长尾由验证主导，优化方向是测试集裁剪与执行槽位扩容，而非继续压缩 B_ctx。反过来，若预填段 P99 高，说明检索召回片段过多或组装顺序导致依赖串行，应回到预算分配。</p>\n<p>具体例子：一个通过编译但测试超时的候选，会把该请求的端到端延迟推到验证段的长尾区，而此时解码早已完成、GPU 处于空闲。这种“GPU 等 CPU 执行”的空转是仓库级生成特有的浪费，测量上应记录验证段的 GPU 空闲占比，作为分离式预填/解码之外的另一条解耦依据。材料未给出延迟数字，因此只能定性表述：验证环节与低延迟补全 SLO 之间存在张力，张力大小取决于测试集规模与执行环境。</p>\n\n<h3 id=\"paper-fastcoder-accelerating-repository-le-2025-sec-9\">九 · 负载塑造方案，方案反向限制负载</h3>\n<p>负载形态塑造方案的三处设计：引用数分桶决定 B_ctx 分配；候选数 k 决定解码与验证的吞吐配比；仓库快照版本决定前缀缓存能否复用。反过来，方案也限制负载：验证器覆盖不全时错误候选漏过形成静默失败，系统会倾向于扩大测试集，而测试集扩大会进一步拉长验证长尾，形成“越求稳越慢”的正反馈。前缀缓存复用检索片段时若不校验快照版本，仓库变更后会复用过期上下文，生成引用已删除符号，这类失败不体现在延迟上，只体现在通过率上。</p>\n<p>可核查的测量口径应把“缓存命中率”与“快照版本一致率”分开统计：命中率高但一致率低，说明缓存策略在拿正确性换延迟。同理，验证通过率要与“验证覆盖率”配对报告——通过率高可能是因为测试集太窄，而非候选真好。材料未给出召回率、漏过率与测试集构造方式，因此这两项只能作为必须补齐的监控项列出，不能给出阈值。</p>\n<p>工程判断落在准入控制上：把 B_ctx、k、验证槽位数三个参数作为联合约束，任一请求的准入需同时满足预填 token 预算、解码 token 预算与验证队列深度三项检查。仓库级请求的长尾不是单点慢，而是三段串联后尾部叠加，只有分段打点加联合准入才能把长尾压到可承诺的范围内。</p>\n\n<h3 id=\"paper-fastcoder-accelerating-repository-le-2025-sec-10\">十 · 可核查的测量清单</h3>\n<p>把上述口径收敛为一张可执行的测量表，每行对应一个必须落盘的字段，缺一项就无法判断瓶颈在哪一段：</p>\n<table class=\"mini\">\n<thead>\n<tr><th>字段</th><th>所属段</th><th>用途</th></tr>\n</thead>\n<tbody>\n<tr><td>引用数、召回片段数、截断片段数</td><td>检索/组装</td><td>判断 B_ctx 是否不足，输出分桶截断率</td></tr>\n<tr><td>预填 token 数、组装顺序深度</td><td>组装/预填</td><td>约束 KV 占用，识别依赖串行</td></tr>\n<tr><td>候选数 k、解码 token 数</td><td>解码</td><td>计算解码侧吞吐需求</td></tr>\n<tr><td>编译耗时、测试耗时、验证队列深度</td><td>验证</td><td>定位长尾来源，计算 GPU 空闲占比</td></tr>\n<tr><td>缓存命中率、快照版本一致率</td><td>缓存</td><td>区分延迟收益与正确性风险</td></tr>\n<tr><td>验证通过率、验证覆盖率</td><td>验证</td><td>配对报告，防止窄测试集虚高</td></tr>\n</tbody>\n</table>\n<p>这张表的用法是逐段归因：端到端 P99 超标时，先看验证段 P99 是否主导，再看预填段是否因截断率上升而反复重试。材料未给出任何具体数值，因此表内字段只定义口径不定义阈值，阈值必须由部署方按自身 SLO 与硬件档位实测标定。最后落在一条工程判断上：B_ctx 不是常量而是按引用数分桶的函数，验证槽位数不是附属资源而是与解码批并列的一等调度对象——把这两点写进准入控制，仓库级生成的负载才不会被验证长尾反向拖垮。</p>\n\n\n<h3 id=\"paper-fastcoder-accelerating-repository-le-2025-sec-11\">十一 · 请求形态如何反向约束检索预算与验证并发</h3>\n<p>仓库级请求的输入长度并不由用户提示决定，而由检索预算 B_ctx 截断：<span class=\"formula\">$$|\\mathrm{ctx}|=\\min!\\left(\\sum_{i\\in\\mathrm{TopK}}|d_i|,\\;B_{\\mathrm{ctx}}\\right)$$</span> 因此预填 token 规模与 KV cache 占用随 B_ctx 线性受控，而非随仓库规模膨胀。代价是预算成为硬边界：小仓库上固定 B_ctx 会浪费预填容量，大仓库上则直接丢掉跨文件定义与调用关系。可核查的测量口径是记录每次请求的检索召回符号数、被截断片段数与截断位置，把“丢失关键符号”从定性风险变成可计数的截断事件率，而不是只看端到端通过率。</p>\n<p>并发与批大小在本方案里被验证环节重新塑形。生成侧一次产出多个候选，候选数线性放大解码开销，而每个候选都要进入编译与测试，验证执行时间计入端到端延迟。于是有效并发不是由 GPU 批调度单独决定，而受验证器吞吐约束：<span class=\"formula\">$$N_{\\mathrm{cand}}\\cdot T_{\\mathrm{verify}}\\le \\mathrm{SLO}_{\\mathrm{e2e}}-T_{\\mathrm{prefill}}-T_{\\mathrm{decode}}$$</span> 低延迟补全场景下右端余量很小，多候选策略会先把预算吃光。测量上应分别打点预填、解码、验证三段耗时并记录候选数，否则无法判断 SLO 违约来自检索质量还是验证排队。</p>\n<p>长尾来自仓库快照与缓存版本。通过验证的片段回写前缀缓存供同仓库后续请求复用，但若复用时不校验仓库快照版本，仓库变更后会命中过期上下文，生成引用已删除符号——这是静默失败，验证器覆盖不全时尤其难发现。工程判断是：把缓存键绑定到仓库快照标识与 B_ctx，命中前做版本比对；同时以验证通过率与验证平均执行耗时两个指标共同筛选，而非只以通过率排序候选，避免验证环节拖垮 SLO。</p>\n<table class=\"mini\"><thead><tr><th>测量项</th><th>口径</th><th>约束对象</th></tr></thead><tbody><tr><td>截断事件率</td><td>被截断片段数/召回片段数</td><td>检索召回质量</td></tr><tr><td>三段耗时</td><td>预填、解码、验证分别打点</td><td>SLO 归因</td></tr><tr><td>缓存命中有效率</td><td>快照版本一致的前缀命中占比</td><td>过期上下文风险</td></tr></tbody></table>\n<h3 id=\"paper-fastcoder-accelerating-repository-le-2025-sec-12\">十二 · 从 B_ctx 到 kernel 选择：预填规模如何决定精度档位</h3>\n<p>检索把上下文压到 <span class=\"inline-math\">B_ctx</span> 之后，预填阶段的矩阵乘规模由三个量决定：批内序列总长 <span class=\"inline-math\">S</span>、隐藏维 <span class=\"inline-math\">H</span>、FFN 中间维 <span class=\"inline-math\">I</span>。仓库级请求的典型形态是\"短批、长序列\"——同一时刻并发请求数不大，但每条请求带着若干文件片段，<span class=\"inline-math\">S</span> 可达数千 token。这决定了 kernel 选择的第一个判断：预填是 compute-bound 还是 memory-bound。用算术强度粗判，<div class=\"formula\">$$\\mathrm{AI}_{\\text{prefill}} \\approx \\frac{2 \\cdot S \\cdot H \\cdot I}{2 \\cdot (S H + H I + S I)\\cdot b_{\\text{bytes}}}$$</div>\n<p>分母里 <span class=\"inline-math\">\\(b_{\\text{bytes}}\\)</span> 是每元素字节数：BF16 为 2，FP8 为 1，NVFP4 为 0.5。同一形状下把权重与激活从 BF16 降到 FP8，算术强度翻倍，kernel 从受 HBM 带宽约束转向受 Tensor Core 吞吐约束。对 FastCoder 这类流水线，这意味着预填段的耗时对精度档位高度敏感，而解码段（每步只处理一个 token）几乎总是 memory-bound，降精度的收益主要体现在权重带宽而非算力。工程判断由此而来：预填用 FP8 甚至 NVFP4 换吞吐，解码段是否跟随降精度要看权重驻留带宽是否成为瓶颈，而不是一刀切。</p>\n<p>具体例子：一个仓库级请求召回 8 个文件片段，组装后 <span class=\"inline-math\">S=4096</span>，模型 <span class=\"inline-math\">H=8192</span>、<span class=\"inline-math\">I=28672</span>。BF16 下该层预填的权重读取量为 <span class=\"inline-math\">\\(H \\cdot I \\cdot 2\\)</span> 字节，约数百 MB 量级；切到 FP8 后减半，NVFP4 再减半。若批内只有这一条请求，权重读取主导延迟，降精度直接缩短首 token 时间；若批内堆到数十条请求，算力成为主导，此时 tcgen05 的 MMA 吞吐才是关键。FastCoder 的验证环节会放大这一判断：候选数线性放大解码开销，而验证执行时间又计入端到端延迟，预填省下来的时间必须大于验证引入的时间，整条流水线才划算。</p>\n\n<h3 id=\"paper-fastcoder-accelerating-repository-le-2025-sec-13\">十三 · FP16/BF16/FP8/NVFP4：四种格式在代码模型上的取舍</h3>\n<p>代码生成的数值特性与自然语言不同：标识符、括号、缩进构成高度结构化的 token 序列，注意力分布尖锐，logit 尾部差异决定采样是否正确。这使精度选择不能只看困惑度。<strong>FP16</strong> 动态范围窄（最大约 65504），代码模型在长上下文下注意力分数与残差累积容易溢出，通常需要 loss scaling 或干脆不用；<strong>BF16</strong> 与 FP32 同指数位，范围足够，是当前代码模型的默认安全档，代价是每元素 2 字节。<strong>FP8</strong> 分 E4M3（尾数 3 位）与 E5M2（尾数 2 位）两种：E4M3 精度更高、范围较窄，适合权重与激活；E5M2 范围大、精度低，适合梯度类场景，推理中较少用于权重。FP8 的关键约束是 per-tensor 或 per-block 缩放因子——缩放选错，尾数位被浪费在无效动态范围上。</p>\n<p><strong>NVFP4</strong> 是 Blackwell 上的 4 位浮点（E2M1），每 16 个元素共享一个 FP8 缩放因子（微块缩放），另有一个 per-tensor 的 FP32 二级缩放。它的表示能力靠\"块内共享指数\"换取：16 个元素落在同一数量级时精度可用，跨数量级剧烈波动的张量则误差显著。代码模型的权重与激活分布相对温和，但注意力输出与 MLP 激活存在离群通道，直接 NVFP4 量化这些通道会引入可见误差。<div class=\"formula\">$$x_q = \\mathrm{round}_{\\text{E2M1}}\\!\\left(\\frac{x}{s_{\\text{block}}}\\right),\\quad s_{\\text{block}}=\\frac{\\max_{i\\in\\text{blk}}|x_i|}{6},\\quad s_{\\text{tensor}}=\\max_{\\text{blk}} s_{\\text{block}}$$</div>\n<p>这里 <span class=\"inline-math\">6</span> 是 E2M1 可表示的最大幅值。误差上界可写成 <span class=\"inline-math\">\\(|x - x_q s| \\le s_{\\text{block}} \\cdot 2^{-2}\\)</span>（尾数 1 位有效位加隐含位），即块内相对误差量级在 1/8 上下，块间由 FP8 缩放承担。代价侧：NVFP4 把权重带宽压到 BF16 的四分之一，解码段每步权重读取时间随之下降，这是它在低延迟补全场景的真正价值；但预填段的 MMA 需要硬件原生支持 4 位输入，否则要先反量化回 FP8/BF16，反而增加一次显存往返。Blackwell 的第五代 Tensor Core 对 FP4 有原生路径，这条路径是否被框架启用，决定了 NVFP4 是省带宽还是白费。</p>\n<p>具体例子：同一层 MLP 权重，BF16 下解码一步读 <span class=\"inline-math\">\\(H\\cdot I \\cdot 2\\)</span> 字节；NVFP4 下读 <span class=\"inline-math\">\\(H \\cdot I \\cdot 0.5\\)</span> 字节外加每 16 元素一个 FP8 缩放（约 0.0625 字节/元素），总带宽约为原来的 28%。若解码段受权重带宽约束，单步延迟近似按此比例下降；若受 KV cache 读取或采样开销约束，收益被稀释。这就是为什么量化收益必须按段核算，而不是按整模型宣称。</p>\n\n<h3 id=\"paper-fastcoder-accelerating-repository-le-2025-sec-14\">十四 · 累加精度：FP32 累加器与分块归约的误差账</h3>\n<p>低精度输入不等于低精度累加。Tensor Core 的 MMA 指令在 FP8/FP4 输入下仍以 FP32 累加，这是精度得以维持的根本。但累加顺序影响误差：一个 <span class=\"inline-math\">K</span> 维点积若串行累加，误差随 <span class=\"inline-math\">K</span> 增长；分块归约（split-K）把长点积切成若干段各自累加再合并，能压低误差但引入额外写回与同步。<div class=\"formula\">$$\\epsilon_{\\text{acc}} \\lesssim \\sqrt{K}\\cdot u_{\\text{fp32}}\\cdot \\sum_k |a_k b_k|,\\qquad u_{\\text{fp32}}=2^{-24}$$</div>\n<p>这是随机游走模型的量级估计：<span class=\"inline-math\">\\(u_{\\text{fp32}}\\)</span> 是 FP32 单位舍入误差，<span class=\"inline-math\">\\(\\sqrt{K}\\)</span> 来自误差的随机累积。它说明两件事：其一，FP8 输入配 FP32 累加时，主导误差来自输入的量化而非累加；其二，若把累加器降到 FP16（部分老 kernel 为省寄存器这么做），<span class=\"inline-math\">u</span> 放大到 <span class=\"inline-math\">2^{-11}</span>，<span class=\"inline-math\">K</span> 上千时误差迅速不可接受。代码模型对 logit 的绝对精度要求不高，但对<em>相对排序</em>敏感——两个候选 token 的 logit 差若被累加误差淹没，采样就偏离。FastCoder 生成多个候选再由验证筛选，某种程度上容忍了这种偏差：概率排序错了，编译与测试还能兜底；但兜底的成本是验证执行时间，所以累加精度仍是延迟账的一部分。</p>\n<p>具体例子：一个 <span class=\"inline-math\">K=8192</span> 的 FFN 上投影，FP8 输入、FP32 累加，<span class=\"inline-math\">\\(\\sqrt{K}\\approx 90\\)</span>，累加误差量级约 <span class=\"inline-math\">\\(90 \\times 6\\times10^{-8} \\approx 5\\times10^{-6}\\)</span> 相对量级，远小于 FP8 输入本身的量化误差（E4M3 尾数 3 位，相对误差约 1/16）。若改用 FP16 累加，<span class=\"inline-math\">u=2^{-11}</span>，误差放大约 8000 倍，量级跳到千分之几，足以改变近距离 token 的排序。工程上因此有一条硬规则：输入可以降到 FP8/FP4，累加器必须留在 FP32，除非有明确的误差预算与实测背书。</p>\n\n<h3 id=\"paper-fastcoder-accelerating-repository-le-2025-sec-15\">十五 · tcgen05 与 TMEM：把累加器搬进张量内存</h3>\n<p>Blackwell 的 tcgen05 系列 MMA 指令改变了累加器的存放位置。此前的 MMA 把累加器放在寄存器堆，寄存器压力限制了 tile 尺寸与流水深度；tcgen05 把累加器放进 <strong>TMEM</strong>（Tensor Memory），一块与 Tensor Core 紧耦合的片上存储，按列划分、由 MMA 直接读写。这带来两个直接后果：寄存器不再被 <span class=\"inline-math\">\\(M\\times N\\)</span> 的累加器占满，kernel 可以把更多资源给流水与异步拷贝；累加结果留在 TMEM 里，后续 epilogue（激活、缩放、写回）可以按需读取，而不必先落寄存器再溢出。</p>\n<p>代价是编程模型的复杂度：TMEM 有容量上限，tile 的 <span class=\"inline-math\">N</span> 维与累加器占用的列数必须匹配；多个 MMA 争用同一块 TMEM 时需要显式分配与同步。伪代码思路大致是：<div class=\"formula\">$$\\text{alloc TMEM}(N_{\\text{cols}}) \\rightarrow \\text{issue tcgen05.mma}(A_{\\text{smem}},B_{\\text{smem}},\\text{acc}_{\\text{tmem}}) \\rightarrow \\text{wait} \\rightarrow \\text{epilogue}(\\text{acc}_{\\text{tmem}})$$</div>\n<p>对 FastCoder 的预填段，TMEM 的价值在于允许更大的 <span class=\"inline-math\">N</span> tile：<span class=\"inline-math\">N</span> 越大，权重复用越高，算术强度越高，越容易把预填推入 compute-bound 区间。对解码段，<span class=\"inline-math\">M</span> 很小（每步一个 token），TMEM 的意义转向减少寄存器压力以容纳更多并发请求的 KV 读取流水。显存侧的间接收益是：预填 tile 变大后，同样的 <span class=\"inline-math\">B_ctx</span> 需要的 kernel 启动次数减少，调度开销下降。</p>\n<p>具体例子：一个 <span class=\"inline-math\">M=128</span>、<span class=\"inline-math\">N=256</span>、<span class=\"inline-math\">K=8192</span> 的预填 tile，FP32 累加器占 <span class=\"inline-math\">\\(128\\times256\\times4\\)</span> 字节即 128 KB。放在寄存器堆里，这已接近单 SM 寄存器文件的上限，流水深度被压到很浅；放进 TMEM 后寄存器释放，双缓冲与异步拷贝可以展开，MMA 与数据搬运重叠。这就是 tcgen05 在长上下文预填上的实际收益来源——不是单条指令更快，而是流水能开得更深。</p>\n\n<h3 id=\"paper-fastcoder-accelerating-repository-le-2025-sec-16\">十六 · 2-SM MMA：跨 SM 协作与通信代价</h3>\n<p>2-SM MMA 让两个 SM 协同执行一条 MMA，把 <span class=\"inline-math\">M</span> 维或 <span class=\"inline-math\">N</span> 维的 tile 跨 SM 拼接，共享同一份权重读取。它的动机是权重带宽：大 <span class=\"inline-math\">N</span> tile 下权重读取是瓶颈，两个 SM 各持一半激活、共用一份权重，等效于把权重带宽减半。<div class=\"formula\">$$T_{\\text{mma}} \\approx \\max\\!\\left(\\frac{W_{\\text{bytes}}}{B_{\\text{w}}},\\ \\frac{2 M N K}{P_{\\text{tc}}}\\right),\\quad W_{\\text{bytes}}\\ \\text{由 2-SM 共享后减半}$$</div>\n<p>第一项是权重读取时间，第二项是算力时间，<span class=\"inline-math\">\\(P_{\\text{tc}}\\)</span> 是 Tensor Core 吞吐。2-SM 协作把第一项的分子减半，但引入跨 SM 的同步与数据交换：两个 SM 必须就 tile 边界、累加器归属、epilogue 分工达成一致，同步点若处理不好，省下的带宽会被等待吃掉。这就是为什么 2-SM MMA 在大 tile、权重主导的场景收益明显，在小 tile、算力主导的场景反而可能退步。</p>\n<p>对 FastCoder 的映射：预填段 <span class=\"inline-math\">S</span> 大、tile 大，2-SM 协作划算；解码段 <span class=\"inline-math\">M=1</span>，tile 小，2-SM 的同步开销大概率盖过带宽收益，应退回单 SM。验证环节的多候选解码会放大解码段的请求数，若把候选并成一批，<span class=\"inline-math\">M</span> 变大，2-SM 的适用边界随之上移——这是一个随负载形态漂移的判断，不能写死。功耗侧，2-SM 协作提高了单次 MMA 的能效（同样的权重读取服务两个 SM 的计算），在功耗受限的部署里是正向因素；但同步逻辑本身消耗时钟，净收益要按 tile 尺寸核算。</p>\n<p>具体例子：<span class=\"inline-math\">M=256</span>、<span class=\"inline-math\">N=256</span>、<span class=\"inline-math\">K=8192</span> 的预填 tile，权重读取量 <span class=\"inline-math\">\\(N\\cdot K \\cdot b\\)</span>。单 SM 执行时该读取量全部由一个 SM 的带宽承担；2-SM 各持 <span class=\"inline-math\">M=128</span> 的激活、共享权重，读取量减半，理论延迟下降接近一半，前提是同步开销小于省下的时间。若 tile 缩到 <span class=\"inline-math\">M=32</span>，算力项已不主导，权重读取减半的收益被同步开销抵消，此时单 SM 更优。</p>\n\n<h3 id=\"paper-fastcoder-accelerating-repository-le-2025-sec-17\">十七 · 精度与验证环节的耦合：误差预算怎么定</h3>\n<p>FastCoder 的特殊之处在于它有一条外部验证链：候选生成后要过编译与测试。这改变了精度决策的逻辑——模型输出的概率误差不再直接决定最终正确性，而是决定<em>候选池里有多少能通过验证</em>。于是误差预算可以放宽，但放宽的代价转移到验证吞吐上。<div class=\"formula\">$$T_{\\text{e2e}} = T_{\\text{retrieve}} + T_{\\text{prefill}}(B_{\\text{ctx}},\\text{prec}) + n_{\\text{cand}}\\cdot T_{\\text{decode}}(\\text{prec}) + n_{\\text{cand}}\\cdot p_{\\text{fail}}\\cdot T_{\\text{verify}}$$</div>\n<p>逐项解释：<span class=\"inline-math\">\\(T_{\\text{retrieve}}\\)</span> 是检索与组装开销，与精度无关；<span class=\"inline-math\">\\(T_{\\text{prefill}}\\)</span> 随 <span class=\"inline-math\">B_ctx</span> 与精度档位变化，降精度缩短它；<span class=\"inline-math\">\\(n_{\\text{cand}}\\)</span> 是候选数，解码开销线性放大；<span class=\"inline-math\">\\(p_{\\text{fail}}\\)</span> 是候选未通过验证的比例，<span class=\"inline-math\">\\(T_{\\text{verify}}\\)</span> 是单次验证的编译加测试时间。降精度会抬高 <span class=\"inline-math\">\\(p_{\\text{fail}}\\)</span>——量化误差让更多候选带语法或语义瑕疵——从而抬高验证项。整条式子说明：精度不是越激进越好，最优点在 <span class=\"inline-math\">\\(T_{\\text{prefill}}\\)</span> 的下降与 <span class=\"inline-math\">\\(p_{\\text{fail}} T_{\\text{verify}}\\)</span> 的上升相抵之处。</p>\n<p>工程判断：对低延迟补全场景，<span class=\"inline-math\">\\(T_{\\text{verify}}\\)</span> 往往是最大单项，此时应保守用 BF16/FP8 压低 <span class=\"inline-math\">\\(p_{\\text{fail}}\\)</span>，而不是追 NVFP4 的预填收益；对离线批量生成场景，验证可并行、<span class=\"inline-math\">\\(T_{\\text{verify}}\\)</span> 被摊薄，激进量化换预填吞吐更划算。这与前文\"预填用 FP8、解码看带宽\"的判断叠加，形成按场景分档的精度策略，而不是全局一个档位。</p>\n<p>具体例子：<span class=\"inline-math\">\\(n_{\\text{cand}}=4\\)</span>，解码段每候选 <span class=\"inline-math\">\\(T_{\\text{decode}}\\)</span> 为数十毫秒量级，验证每次编译加测试为数百毫秒量级。若 <span class=\"inline-math\">\\(p_{\\text{fail}}\\)</span> 从 0.3 抬到 0.5，验证项增加约 <span class=\"inline-math\">\\(4\\times0.2\\times T_{\\text{verify}}\\)</span>，足以吞掉预填降精度省下的时间。这就是为什么 FastCoder 的精度决策必须和验证吞吐一起算——单看预填加速会得出错误结论。前缀缓存复用检索片段时同样受精度影响：缓存的是 token 序列而非激活，精度档位切换不破坏缓存，但同一仓库请求若在不同精度档位间漂移，<span class=\"inline-math\">\\(p_{\\text{fail}}\\)</span> 的统计基线会失稳，监控应把精度档位作为维度记录下来。</p>\n\n\n<h3 id=\"paper-fastcoder-accelerating-repository-le-2025-sec-18\">十八 · 检索预算与验证开销夹击下的数值精度边界</h3>\n<p>FastCoder 的流水线把预填规模压到 B_ctx 以内，但检索压缩并不改变生成侧对精度的敏感度：代码生成是符号级任务，标识符、括号与类型注解的错一位就会编译失败。在 Blackwell 上把生成模型压到 FP8 或 NVFP4 时，权重与激活的量化误差会直接放大到 token 概率分布的长尾上，而代码 token 恰恰落在长尾。以 FP8 E4M3 为例，其可表示尾数为 3 位，相对量化步长约 2^-4；若某标识符在词表中与近邻符号的 logit 差距小于该步长对应的扰动，贪心解码就可能翻转。tcgen05 的 2-SM MMA 把两个 SM 的 Tensor Core 配对执行同一矩阵乘，单次 MMA 的 K 维累加在 TMEM 中完成，累加器保持 FP32，因此矩阵乘内部的累加误差可控；真正的风险在量化入口——把 BF16 激活转成 NVFP4（E2M1，块级缩放）时，块内动态范围被压缩到 4 位尾数，跨文件符号的稀有嵌入容易落到同一缩放块内被抹平。</p>\n<div class=\"formula\">$$\\varepsilon_{\\mathrm{rel}}\\approx\\frac{\\Delta_q}{\\lvert x\\rvert},\\quad \\Delta_q=\\frac{\\max_{b}\\lvert x\\rvert}{2^{m-1}},\\quad m\\in\\{3,2,1\\}$$</div>\n<p>式中 Δ_q 为块内量化步长，m 为尾数位数：FP8 E4M3 取 m=3，NVFP4 E2M1 取 m=1，块最大值由缩放因子归一。逐项看：分子是块内最大绝对值，分母是尾数可分辨的格点数，比值给出该块内任意元素的最大相对误差上界；元素绝对值远小于块最大值时，实际相对误差远大于该上界，这正是稀有符号被吞掉的机制。工程代价上，FP8 相对 BF16 把权重带宽减半、Tensor Core 吞吐翻倍，NVFP4 再减半，但代码模型的词表嵌入与 LM head 对精度最敏感，通常需要保留 BF16 或至少 FP8 高精度路径，混合精度会引入额外的 cast kernel 与 TMEM 往返，抬高每 token 的 kernel 启动开销。具体例子：一个仓库级请求召回 12 个片段、B_ctx 设为数千 token，若生成侧用 NVFP4 且未对嵌入层做离群值保护，模型可能把 `std::vector` 生成成近邻的合法但错误的符号，验证器编译失败后候选被丢弃，多候选解码开销白付——这正是验证环节与低精度生成叠加时的典型失效。</p>\n<table class=\"mini\"><thead><tr><th>精度档</th><th>尾数位</th><th>权重带宽</th><th>主要风险</th></tr></thead><tbody><tr><td>BF16</td><td>7</td><td>基准</td><td>无量化误差，带宽与算力代价最高</td></tr><tr><td>FP8 E4M3</td><td>3</td><td>约减半</td><td>长尾 logit 翻转，需 per-block 缩放</td></tr><tr><td>NVFP4 E2M1</td><td>1</td><td>约再减半</td><td>块内动态范围塌缩，稀有符号被抹平</td></tr></tbody></table>\n<p>边界条件由此清晰：检索召回充分、候选经编译测试过滤时，低精度生成只是把失败候选推给验证器，代价是多候选解码与验证执行时间计入端到端延迟；而验证器覆盖不全时，量化引入的符号级错误会静默漏过，形成比 BF16 下更隐蔽的失败。前缀缓存复用同一仓库的已检索上下文时，若仓库快照版本变化而缓存未失效，低精度路径下复用过期片段的错误更难被编译捕获。因此在 Blackwell 上部署该流水线，量化档位应与验证覆盖率绑定：验证覆盖高时可激进用 FP8 换吞吐，验证薄弱时必须保留 BF16 嵌入与 LM head，并把 tcgen05 的 FP32 累加路径固定下来，避免用低精度累加器换取那一点 TMEM 容量。</p>\n</p></p></p></p></p></p>\n\n<h3 id=\"paper-fastcoder-accelerating-repository-le-2025-sec-19\">十九 · 显存账本的三本账：权重、激活、KV</h3>\n<p>在 Blackwell 上做仓库级代码推理，显存不是一块整账，而是三本互相挤占的账：权重、激活、KV cache。权重是静态的，按模型参数量与数值精度一次性占位；激活是动态的，随批大小、序列长度与算子切分方式起伏；KV cache 则是随并发与上下文长度线性增长的那本账，也是仓库级推理最先撑爆的一本。FastCoder 的工程价值在于它把第三本账的规模从“仓库有多大”改写成“检索预算 B_ctx 有多大”，于是 KV 占用从不可控变为可预算。</p>\n<p>设层数 $L$、KV 头数 $H_{kv}$、头维 $d_h$、每元素字节数 $b$、序列长度 $S$、并发批 $N$，则 KV 账本的字节数为：</p>\n<div class=\"formula\">$$\\mathrm{KV}_{\\text{bytes}} = 2 \\cdot L \\cdot H_{kv} \\cdot d_h \\cdot b \\cdot S \\cdot N$$</div>\n<p>系数 2 来自 K 与 V 两份。这个式子说明三件事：KV 对 $S$ 与 $N$ 都是线性的，对精度 $b$ 也是线性的，而层数与头数由模型固定，是部署时无法谈判的部分。FP8 相对 BF16 直接把 $b$ 减半，NVFP4 再减半，但 KV 的量化要单独评估数值稳定性，不能与权重精度混为一谈。以 B200 的 HBM3e 容量为量级参照，单卡容量决定了在给定 $S$ 下能撑住多少并发 $N$，这就是容量规划的起点：先算单请求 KV 占用，再用剩余显存除以它得到并发上限。</p>\n<p>代价落在带宽上。解码阶段每生成一个 token 都要把全部 KV 读一遍，KV 越大，每 token 的 HBM 读带宽越高，解码就越接近带宽瓶颈而非算力瓶颈。仓库级请求的 $S$ 被 B_ctx 截断后，KV 读带宽随之下降，这是 FastCoder 压缩上下文带来的直接收益；但多候选解码会线性放大解码开销，候选数与验证吞吐必须匹配，否则省下的 KV 带宽会被重复解码吃掉。</p>\n\n<h3 id=\"paper-fastcoder-accelerating-repository-le-2025-sec-20\">二十 · 分页与复用：把 KV 从连续块变成可调度资源</h3>\n<p>连续分配的 KV 块在变长请求下会产生严重碎片：一个仓库级请求的上下文长度由检索结果决定，长度分布高度不均，按最大长度预留会浪费大量显存。分页 KV 把缓存切成固定大小的页，按 token 逐个追加分配，逻辑上连续、物理上离散，于是显存利用率由“最坏情况预留”变为“按实际 token 计费”。分页的另一半价值是前缀共享：同一仓库的多个请求共享同一段检索上下文，这些页可以被多个序列引用而无需复制。</p>\n<p>FastCoder 的回写机制正好落在这一点上：通过验证的片段与结果写入前缀缓存，后续同仓库请求复用已检索上下文，减少重复预填。工程上要把它实现成引用计数而非拷贝，页的生命周期由引用数决定，最后一个引用释放时才回收。伪代码思路是：请求到达时先按仓库快照哈希查前缀页表，命中则挂接已有页并只对新增 token 分配新页；未命中则走完整预填。这里的关键判断是仓库快照版本必须参与键的构造，否则仓库变更后会复用过期上下文，生成引用已删除符号，形成静默失败。</p>\n<p>代价在页表管理与命中率上。页粒度越小碎片越少但页表越大，元数据开销上升；命中率取决于同仓库请求的重复度，仓库级生成中同一文件的多次修改请求是主要复用来源。复用省下的是预填算力与 KV 写入带宽，但省不掉解码阶段的 KV 读带宽，因为解码仍要读全部上下文页。因此前缀缓存对首 token 延迟的改善明显，对稳态解码吞吐的改善有限，容量规划时要把这两笔收益分开算。</p>\n\n<h3 id=\"paper-fastcoder-accelerating-repository-le-2025-sec-21\">二十一 · 压缩与卸载：结构压缩、量化与分层放置</h3>\n<p>KV 压缩有三条可叠加的路径：结构压缩（按重要性丢弃或合并 token）、量化压缩（降低每元素字节数）、以及卸载（把冷页放到更低带宽的层级）。结构压缩对代码场景有特殊性，标识符、括号与缩进构成强结构信号，按结构边界整块保留比按注意力分数逐 token 丢弃更能保住可编译性；这一点与结构感知的 KV 压缩思路同源，本片段只取其对显存账本的影响：压缩率直接乘在 $S$ 上，等价于把 B_ctx 的有效容量放大。</p>\n<p>量化压缩把 $b$ 从 2 字节降到 1 字节甚至更低，KV 账本线性缩小，但要注意 K 与 V 的敏感度不同，K 的量化误差会通过注意力分数放大，通常需要分组缩放或保留少量高精度通道。卸载则把不活跃序列的页搬到主机内存，代价是 PCIe 往返延迟；对仓库级请求，检索阶段的长上下文在生成开始后大部分页不再被写入，只有读，因此适合在解码前把低频页下沉，但每次读回都计入解码延迟，卸载比例必须由 SLO 反推而非拍脑袋。</p>\n<p>代价的量化方式是：压缩率 $r$ 使 KV 账本变为 $r \\cdot \\mathrm{KV}_{\\text{bytes}}$，卸载比例 $u$ 使 HBM 占用变为 $(1-u)$ 倍，但解码每 token 的读带宽变为原值加上 $u$ 比例的跨链路读。三者不是免费的叠加，压缩可能损失精度，卸载可能拉高尾延迟，工程判断是先用分页与前缀复用榨干免费收益，再动压缩与卸载。</p>\n\n<h3 id=\"paper-fastcoder-accelerating-repository-le-2025-sec-22\">二十二 · 一个可复算的显存预算</h3>\n<p>下面给出一个只依赖给定参数结构的预算模板，读者可代入自己模型的层数、KV 头数、头维与精度自行复算，本片段不填任何未经给出的实验数字。</p>\n<table class=\"mini\">\n<thead><tr><th>账本项</th><th>决定因素</th><th>随什么线性变化</th><th>可控手段</th></tr></thead>\n<tbody>\n<tr><td>权重</td><td>参数量 × 每参数字节</td><td>模型规模、精度</td><td>FP8/NVFP4 量化、张量并行切分</td></tr>\n<tr><td>激活</td><td>批大小 × 序列长度 × 隐藏维</td><td>批、$S$、算子切分</td><td>分块、重计算、批上限</td></tr>\n<tr><td>KV cache</td><td>$2 L H_{kv} d_h b S N$</td><td>$S$、$N$、$b$</td><td>B_ctx 截断、分页、前缀复用、量化、卸载</td></tr>\n</tbody>\n</table>\n<p>复算顺序是：先由模型规格算出单 token KV 字节数 $k = 2 L H_{kv} d_h b$，再用 B_ctx 乘出单请求 KV 占用 $k \\cdot B_{\\mathrm{ctx}}$；用 HBM 容量减去权重与激活峰值，得到可用 KV 池；池容量除以单请求占用得到理论并发上限，再乘以分页碎片系数与前缀命中带来的折算，得到可承诺并发。这个链条里唯一由 FastCoder 直接约束的参数是 B_ctx，其余由部署方选择。</p>\n<div class=\"formula\">$$N_{\\max} = \\left\\lfloor \\frac{C_{\\mathrm{HBM}} - W - A_{\\text{peak}}}{k \\cdot B_{\\mathrm{ctx}} \\cdot \\eta} \\right\\rfloor$$</div>\n<p>其中 $\\eta$ 是分页与复用的有效折算系数，$W$ 为权重占用，$A_{\\text{peak}}$ 为激活峰值。举例说明量级关系而非具体数值：若把 B_ctx 从全仓库拼接的规模压到检索预算，单请求 KV 占用按比例下降，$N_{\\max}$ 按同一比例上升，这就是“把长上下文压力转化为检索质量问题”在显存账本上的确切含义。反过来，若检索预算设成固定常量而不随仓库规模调整，小仓库浪费预算、大仓库丢关键符号，账本上表现为并发上不去而召回又不够，两头受损。</p>\n\n<h3 id=\"paper-fastcoder-accelerating-repository-le-2025-sec-23\">二十三 · 带宽瓶颈的位置与验证环节的显存代价</h3>\n<p>解码阶段的带宽瓶颈位置取决于批大小：小批时每 token 只读一份 KV 与全部权重，权重读带宽占主导，属于权重带宽受限；大批时 KV 读带宽随 $N$ 增长并超过权重项，转为 KV 带宽受限。仓库级请求的 $S$ 大，KV 项更早越过权重项，因此压缩 B_ctx 对大批解码的带宽收益更明显。预填阶段则是算力受限，B_ctx 截断直接减少预填 FLOPs，首 token 延迟随之下降，这与 KV 写入量同步下降。</p>\n<p>验证环节的代价不在 GPU 显存而在流水线占用：候选要离开解码循环进入编译与测试，验证器本身占用主机侧资源，且验证执行时间计入端到端延迟。多候选会线性放大解码开销，若候选数为 $m$，解码侧 KV 读带宽与算力近似乘 $m$，而验证吞吐是外部瓶颈，两者不匹配时 GPU 会在等待验证时空转。工程判断是把候选数当作调度参数而非固定值：验证队列积压时降低 $m$，验证空闲时提高 $m$，用队列深度做反馈，而不是让解码侧无节制地产生候选。</p>\n<p>另一个常被忽略的账本是前缀缓存本身的显存占用：复用的页长期驻留会挤占新请求的 KV 池，必须有淘汰策略。按仓库快照版本与最近使用时间做两级淘汰，仓库变更即失效，比单纯 LRU 更能避免过期上下文复用。这一步的代价是页表查询与失效扫描的元数据开销，量级远小于重算预填，属于划算的交换。</p>\n\n<h3 id=\"paper-fastcoder-accelerating-repository-le-2025-sec-24\">二十四 · 工程判断：预算先于压缩，复用先于卸载</h3>\n<p>把上面几条收敛成可执行的顺序：先用 B_ctx 把单请求 KV 占用压到可预算范围，再用分页消除碎片，再用前缀复用吃掉同仓库重复预填，最后才考虑量化压缩与卸载。这个顺序的理由是前两步不损失精度也不引入跨链路延迟，第三步只损失快照校验的元数据开销，后两步才动数值与延迟。仓库级代码生成的失败模式里，检索召回不足与验证漏过都是正确性问题，不能用显存手段掩盖；显存手段只解决容量与带宽，不解决召回。</p>\n<p>具体机制上，落地检查点是三个可观测项：单请求 KV 占用是否随 B_ctx 线性受控、前缀命中是否按仓库快照正确失效、解码侧 KV 读带宽是否随批大小越过权重项。三者任一失守，容量规划就会偏离。最后一段落在判断上：在 Blackwell 的 HBM3e 容量下，仓库级推理的并发上限由 $k \\cdot B_{\\mathrm{ctx}}$ 这一项主导，而这一项由检索预算而非仓库规模决定，因此把 B_ctx 做成随仓库规模与请求类型自适应的变量，比任何离线压缩都更能稳住显存账本。</p>\n\n<h3 id=\"paper-fastcoder-accelerating-repository-le-2025-sec-25\">二十五 · 预算封顶后的显存账本与失效边界</h3>\n<p>把 B_ctx 当作硬约束后，显存账本才可复算。单请求 KV 占用可写成 <span class=\"formula\">$$M_{\\mathrm{KV}}=2\\cdot L\\cdot H_{\\mathrm{kv}}\\cdot d_h\\cdot B_{\\mathrm{ctx}}\\cdot b_{\\mathrm{kv}}$$</span>，其中 L 为层数、H_kv 为 KV 头数、d_h 为头维、b_kv 为每元素字节数（FP8 取 1、BF16 取 2），系数 2 对应 K 与 V。权重与激活是常量项，KV 才是随并发线性增长的可变项，因此并发上限近似为 <span class=\"formula\">$$N_{\\max}\\approx\\frac{C_{\\mathrm{HBM}}-M_{\\mathrm{w}}-M_{\\mathrm{act}}-M_{\\mathrm{rsv}}}{M_{\\mathrm{KV}}}$$</span>。举例：若某层配置使单请求 KV 落在数百 MB 量级，则单卡剩余容量除以该值即为可服务的并发请求数；检索压缩把 B_ctx 从全仓库规模压到受控长度，直接按比例缩小分母，这是该方案对显存账本唯一的杠杆。</p>\n<p>代价转移而非消失。检索器本身要持有仓库索引的向量与符号表，这部分常驻显存或主机内存，规模随仓库文件数增长；前缀缓存回写又要求把已检索片段与验证结果驻留，缓存命中才省预填，未命中则退化为重复检索加重复预填。多候选解码线性放大激活与临时缓冲，候选数 K 与验证吞吐必须匹配，否则解码侧排队而验证侧空转。带宽瓶颈落在两处：预填阶段读权重与写 KV 的 HBM 往返，以及验证阶段把候选送入编译测试环境时的主机侧拷贝；前者随 B_ctx 缩小而缓解，后者不随检索压缩改善。</p>\n<table class=\"mini\"><thead><tr><th>失效条件</th><th>系统表现</th><th>工程对策</th></tr></thead><tbody><tr><td>B_ctx 固定不随仓库规模调整</td><td>小仓库浪费预填预算，大仓库丢跨文件符号</td><td>按仓库规模与请求类型分档设预算</td></tr><tr><td>前缀缓存未校验仓库快照版本</td><td>复用过期上下文，引用已删除符号</td><td>缓存键绑定 commit 或快照哈希</td></tr><tr><td>验证执行延迟未计入 SLO</td><td>低延迟补全被编译测试拖垮</td><td>按场景分级：补全走轻验证，提交走全验证</td></tr></tbody></table>\n<p>边界判断落在召回率与验证覆盖率两条曲线上：召回不足时压缩上下文缺失关键定义，模型只能凭参数记忆补符号，编译失败率上升，验证环节被迫承担更多过滤工作，端到端延迟被验证执行时间主导；验证覆盖不全时错误候选静默通过，前缀缓存还会把错误上下文固化给后续请求。因此该方案适合仓库快照稳定、测试可执行、SLO 允许百毫秒级以上验证开销的批量生成场景，不适合要求极低首 token 延迟的交互式补全；后者应把验证降级为语法与类型检查，把编译测试移出关键路径。</p>\n<h3 id=\"paper-fastcoder-accelerating-repository-le-2025-sec-26\">二十六 · 从“三段流水线”到“可调度队列”：请求形态决定批处理结构</h3>\n<p>FastCoder 的推理路径是检索→生成→验证三段，但三段的时间尺度完全不同：检索是毫秒级的索引查询，生成是数十到数百毫秒级的自回归解码，验证则是编译加测试，耗时取决于工具链与测试规模，且方差极大。把这三段塞进同一个同步请求处理循环，等于让最慢的验证段决定整条队列的推进节奏，连续批处理无从谈起。工程上的做法是把流水线切成两个可独立调度的阶段：检索与上下文组装在 CPU 侧或前置服务完成，产出一个受 B_ctx 约束的提示；生成与验证进入 GPU 侧的调度器，生成以 token 为粒度做连续批处理，验证则作为异步后处理与下一批生成重叠。这样，验证的长尾不会阻塞解码器空转。</p>\n<p>关键在于候选数量的放大效应。生成侧一次产出多个候选，解码开销随候选数线性增长，而验证吞吐由编译与测试环境决定，两者若不匹配，就会出现“解码等验证”或“验证队列积压”。设单请求候选数为 k、单候选平均解码 token 数为 L、验证单候选平均耗时为 T_v，则单请求的生成侧 GPU 时间约为 k·L·t_tok（t_tok 为单 token 解码时间），验证侧墙钟时间约为 k·T_v。当 k·T_v > k·L·t_tok 时，瓶颈在验证；此时提高批内并发只会加剧验证积压，正确动作是限制每批的候选总数并让验证并发度与 CPU/工具链容量对齐，而不是继续堆 GPU 批大小。这是本流水线区别于纯生成服务的第一条调度约束。</p>\n<p>具体例子：一个仓库级函数生成请求，B_ctx 截断后提示为数千 token 量级，模型解码出若干候选，其中一部分在编译阶段即失败。若把验证同步串在解码之后，解码器在验证期间完全空闲；改为异步验证后，解码器可以立即开始下一请求的预填，验证结果以回调方式回写前缀缓存。代价是需要在调度器中维护“已生成未验证”的在途候选计数，并对其设上限，否则显存中的候选 KV 与中间状态会无界增长。</p>\n\n<h3 id=\"paper-fastcoder-accelerating-repository-le-2025-sec-27\">二十七 · 连续批处理与 chunked prefill：把 B_ctx 变成可切分的预填预算</h3>\n<p>FastCoder 用检索压缩上下文，直接效果是把预填 token 规模从“随仓库规模膨胀”变为“受 B_ctx 约束”。但 B_ctx 仍是一个不小的数——数千 token 的提示在解码开始前必须一次性完成注意力计算，这段预填是首 token 延迟（TTFT）的主要成分。连续批处理解决的是解码阶段的批内空洞：不同请求的解码长度不同，短请求完成后空出的槽位立即被新请求填充，避免整批等待最长序列。而 chunked prefill 解决的是预填与解码争抢算力的矛盾：把长提示切成若干块，与正在解码的请求拼在同一批里，使解码 token 不被长预填长时间阻塞。</p>\n<p>伪代码思路如下：调度器每步从等待队列取新请求，按其提示长度与当前批内已占 token 预算比较，若剩余预算不足以容纳整段提示，则只切出可容纳的 chunk 送入本步前向，剩余部分留待后续步；同时把处于解码态的请求各取一个 token 一并计算。批内 token 预算 B_step 是核心参数，它同时约束了单步计算量与 KV cache 的瞬时写入量。</p>\n<div class=\"formula\">$$\\mathrm{TTFT}\\approx \\frac{|\\mathrm{ctx}|}{B_{\\mathrm{step}}}\\cdot t_{\\mathrm{step}}+t_{\\mathrm{attn}}(|\\mathrm{ctx}|),\\quad |\\mathrm{ctx}|\\le B_{\\mathrm{ctx}}$$</div>\n<p>这里 t_step 是单步前向的固定开销，t_attn 是随上下文长度增长的注意力代价。公式的含义很直接：TTFT 由“预填被切成多少步”决定，而步数由 B_step 与 B_ctx 的比值决定。把 B_step 调大能减少步数、压低 TTFT，但会挤占解码请求的槽位，抬高解码的 token 间延迟（ITL）；调小则相反。对代码补全这类低延迟场景，B_step 应向预填倾斜；对仓库级整函数生成这类吞吐优先场景，可让解码优先、预填让步。代价体现在显存带宽上：chunked prefill 使 KV cache 的写入分散到多步，单步写入量下降，但总写入量不变，且分块边界带来的额外 kernel 启动开销会小幅抬高单步时间。</p>\n<p>具体例子：同一仓库的多个请求共享已检索片段，前缀缓存命中后，预填只需计算新增的目标签名与少量差异片段，|ctx| 大幅缩小，TTFT 随之下降。这正是 FastCoder 把检索结果回写前缀缓存的调度价值：它不只是省显存，更是把预填预算从“每请求全量”变成“每仓库增量”，让 chunked prefill 的切分粒度可以更粗、步数更少。</p>\n\n<h3 id=\"paper-fastcoder-accelerating-repository-le-2025-sec-28\">二十八 · 优先级与抢占：验证通过率作为调度信号</h3>\n<p>仓库级代码生成的 SLO 不是单一延迟指标，而是“一次通过率 × 端到端延迟”的组合。验证器返回的编译与测试结果，恰好是一个可用的在线质量信号：同一仓库、同一类目标签名下，历史验证通过率高的请求，其候选更可能一次通过，值得给更高的调度优先级；通过率低的请求则需要更多候选与更长验证，应被放到低优先级队列，避免其长尾拖累整体尾延迟。这不是猜测式启发，而是把验证结果作为反馈闭环接入调度器——FastCoder 的“回写与缓存”环节本就记录了验证结果，调度器可以直接消费这份记录。</p>\n<p>抢占的实现要点在于 KV cache 的可回收性。当高优先级请求到达而 GPU 批已满时，调度器需要驱逐低优先级请求的 KV 块。被驱逐的请求若已生成部分候选，其解码状态必须能恢复：要么把已生成 token 与 KV 块换出到主机内存，要么直接丢弃并从提示重新预填。前者省算力但占带宽，后者省显存但重复预填。对 FastCoder 而言，由于提示受 B_ctx 约束且前缀缓存可复用，丢弃重预填的代价被压低，因此在显存紧张时“丢弃并重排”往往比“换出再换入”更划算。</p>\n<p>代价要算清楚：抢占本身引入调度抖动，被抢占请求的端到端延迟被拉长，尾延迟（p99）可能反而变差。工程判断是给抢占设阈值——只有当高优先级请求的等待时间超过某界限、或低优先级请求已占用超过其配额时，才触发驱逐；否则让高优先级请求排队。具体例子：一个交互式补全请求与一批离线仓库扫描请求共享同一 GPU，若不加优先级，离线批的长验证会占满验证并发度，补全请求的候选排在队尾，p99 被显著拉高；引入按验证通过率与请求类型分级的队列后，补全请求的候选获得验证优先权，离线批在空闲槽位填充，两者尾延迟解耦。</p>\n\n<h3 id=\"paper-fastcoder-accelerating-repository-le-2025-sec-29\">二十九 · 分离式预填/解码：把预填的算力密集与解码的带宽密集拆开</h3>\n<p>预填阶段是算力密集的：大矩阵乘、长序列注意力，GPU 的 tensor core 利用率高；解码阶段是带宽密集的：每步只算一个 token，权重读取占主导，算力大量闲置。把两者放在同一组 GPU 上跑，必然出现“预填时解码饿死、解码时算力浪费”的交替。分离式预填/解码（PD 分离）把预填放到一组实例、解码放到另一组实例，KV cache 通过高速互联从预填侧传到解码侧。Blackwell 世代的 NVLink 5 与机架级 NVL72 拓扑使这种 KV 传输的带宽代价可控，而 NIXL 这类传输库提供了点对点 KV 搬运的抽象。</p>\n<p>对 FastCoder 而言，PD 分离的收益点在于：检索压缩后的 B_ctx 使预填侧的单请求工作量可预测，预填实例可以按 B_ctx 与到达率做容量规划；解码侧则按候选数与解码长度规划，两侧的扩缩容解耦。代价是 KV 传输引入额外延迟与带宽占用，且预填与解码的比例必须匹配——预填侧产出 KV 的速度若超过解码侧消费速度，KV 会在传输队列中积压；反之解码侧会空等。设预填侧吞吐为 R_p（token/s）、解码侧消费为 R_d，稳态要求 R_p ≈ R_d，比例失配时需要通过批大小或实例数调整。</p>\n<p>具体例子：仓库级请求的提示经检索压缩后长度集中在一个较窄区间，预填侧可以用固定 chunk 大小流水线化处理，多个请求的预填 chunk 拼批以提高算力利用率；解码侧接收 KV 后按连续批处理推进，验证异步进行。这样预填侧的尾延迟不再被解码侧的长候选拖累，解码侧的 ITL 也不再被突发预填打断。工程上要监控的是 KV 传输的 p99 与两侧队列深度，任一指标恶化都说明预填/解码配比需要重调。</p>\n\n<h3 id=\"paper-fastcoder-accelerating-repository-le-2025-sec-30\">三十 · 尾延迟怎么压：验证异步化、候选配额与缓存版本校验</h3>\n<p>尾延迟的来源在本流水线里很集中：验证环节的执行时间方差、多候选解码的长尾、以及前缀缓存复用过期上下文导致的返工。压尾延迟的第一个动作是把验证彻底移出关键路径——候选生成后立即返回“已提交验证”的句柄，验证结果异步回写；对交互式场景，可以先返回通过编译的最短候选，测试结果后补。第二个动作是给每请求的候选数设硬配额，候选数 k 直接线性放大解码与验证开销，k 无上限时尾延迟必然失控；配额应按请求优先级与历史验证通过率动态调整，通过率高的请求给更少候选即可。</p>\n<p>第三个动作是缓存版本校验。FastCoder 把通过的片段与结果写入前缀缓存供同仓库后续请求复用，但仓库快照会变；若复用过期上下文，生成会引用已删除符号，验证阶段才暴露，等于把一次本可避免的失败拖到端到端延迟的末端。调度器在命中前缀缓存时必须比对仓库快照版本，版本不符则失效该缓存条目并重新检索。这一步的代价是一次版本比对与可能的重新预填，收益是消除一类静默失败带来的长尾。</p>\n<p>表格对比三类调度动作的代价与收益：</p>\n<table class=\"mini\"><thead><tr><th>动作</th><th>主要代价</th><th>压尾延迟的机制</th><th>适用场景</th></tr></thead><tbody><tr><td>验证异步化</td><td>需维护在途候选计数与结果回调</td><td>解码器不被验证长尾阻塞</td><td>交互式补全、高并发仓库请求</td></tr><tr><td>候选配额</td><td>可能降低一次通过率的期望上限</td><td>切断 k 对解码与验证开销的线性放大</td><td>验证吞吐受限的部署</td></tr><tr><td>缓存版本校验</td><td>版本比对与可能的重新预填</td><td>消除过期上下文导致的末端失败</td><td>仓库频繁变更的团队</td></tr></tbody></table>\n<p>最后落在一条工程判断上：FastCoder 的调度设计不应追求单一吞吐最大化，而应把 B_ctx、B_step、候选配额 k、验证并发度四个参数作为一组联立约束来调。B_ctx 决定预填规模与前缀缓存的复用粒度，B_step 决定 TTFT 与 ITL 的分配，k 决定解码与验证的负载比，验证并发度决定长尾能否被吸收。四者中任一被当作固定常量而不随仓库规模、请求类型与验证环境调整，都会在某一类负载下把尾延迟推高——这正是该流水线在 Blackwell 部署时需要逐仓库标定的部分。</p>\n<h3 id=\"paper-fastcoder-accelerating-repository-le-2025-sec-31\">三十一 · 切分维度：检索流水线里谁在并行</h3>\n<p>仓库级代码生成的推理流水线不是单一模型的单次前向，而是“检索—组装—生成—验证”四段串联。并行切分必须按段选择：生成段吃的是解码算力与 KV 带宽，适合 TP 与 EP；检索段吃的是索引查询与向量距离计算，天然适合 DP 复制；验证段吃的是编译与测试的 CPU 与外部进程，既不该占用 GPU 的 TP 组，也不该与解码共享同一批流。把四段强行塞进一个同构并行组，是这类系统最常见的拓扑错误。FastCoder 的材料没有给出并行拓扑，因此本部分讨论的是部署时必须自行决定的切分判断，而不是复述论文配置。</p>\n<p>以 GB200 NVL72 一柜为例：生成侧若采用 TP=8 的 8 卡组，单组内每层注意力的 All-Reduce 走 NVLink 5 域内；检索侧用 DP=8 的独立进程组，每份副本持有完整索引分片，查询请求按哈希路由；验证侧则以 CPU 池加容器沙箱运行，与 GPU 组通过 NIXL 或主机内存搬运候选代码与测试产物。三段之间用异步队列解耦，生成组不必等待验证组返回即可继续解码下一批候选——这正是把验证开销从解码关键路径上剥离的唯一手段。</p>\n<div class=\"formula\">$$\\mathrm{TP_{gen}}=G_{\\mathrm{node}},\\quad \\mathrm{DP_{ret}}=N_{\\mathrm{replica}},\\quad \\mathrm{PP}=\\left\\lceil \\frac{L_{\\mathrm{layers}}}{L_{\\mathrm{stage}}} \\right\\rceil$$</div>\n<p>代价判断：TP 组越大，单次解码步的 All-Reduce 消息越大、参与同步的 SM 越多，解码步延迟随组规模上升；而 DP 复制检索副本只增加显存占用（每副本一份索引或索引分片），不增加通信。因此在显存允许时，优先把并行度花在检索的 DP 上，把生成侧 TP 控制在单节点 NVLink 域内，避免跨节点 TP 把每步解码拖进 InfiniBand 时延。</p>\n\n<h3 id=\"paper-fastcoder-accelerating-repository-le-2025-sec-32\">三十二 · NVLink 5 与 NVSwitch：域内带宽决定 TP 上限</h3>\n<p>Blackwell 机柜内 NVLink 5 与 NVSwitch 构成全互联域，TP 组内每层注意力的 All-Reduce 与 EP 的 All-to-All 都落在这个域里。TP 的通信量与隐藏维度和批内 token 数成正比：每层两次 All-Reduce，每次搬运约 2×(batch×seq×hidden) 字节的激活。解码阶段 batch×seq 很小，单次消息只有几十到几百 KB，此时瓶颈不是带宽而是固定时延与同步开销；预填阶段 seq 很大，消息量陡增，带宽才成为主约束。这解释了为什么同一 TP 组在预填与解码两段的通信表现完全不同。</p>\n<p>具体例子：一个 8 卡 TP 组在预填一个 B_ctx 被截断到受控长度的仓库上下文时，每层 All-Reduce 的消息量随 seq 线性放大，预填阶段的通信时间占比显著高于解码阶段；而在逐 token 解码时，每步只需同步极小激活，NVLink 5 的带宽远未饱和，真正拖慢的是跨 SM 的 barrier 与 kernel 启动。工程判断是：预填与解码应使用不同的并行策略——预填可走更大 TP 或 PP 摊薄单卡激活，解码则应缩小 TP、增大 DP 副本数以提升并发请求数。</p>\n<table class=\"mini\"><thead><tr><th>阶段</th><th>通信形态</th><th>主导代价</th><th>切分倾向</th></tr></thead><tbody><tr><td>预填</td><td>TP All-Reduce，消息随 seq 放大</td><td>NVLink 带宽</td><td>大 TP 或 PP 摊薄激活</td></tr><tr><td>解码</td><td>TP All-Reduce，消息极小</td><td>同步时延、kernel 启动</td><td>小 TP、多 DP 副本</td></tr><tr><td>EP 路由</td><td>All-to-All，token 分发</td><td>域内带宽与路由均衡</td><td>EP 组限制在单节点域</td></tr><tr><td>验证回传</td><td>NIXL 点对点搬运</td><td>主机内存与 PCIe</td><td>与 GPU 组解耦</td></tr></tbody></table>\n\n<h3 id=\"paper-fastcoder-accelerating-repository-le-2025-sec-33\">三十三 · All-to-All 与 All-Reduce：EP 的代价在哪</h3>\n<p>MoE 代码模型的 EP 切分把专家分散到不同卡，每个 token 需经 All-to-All 被路由到持有目标专家的设备，算完再 All-to-All 送回。仓库级生成的多候选解码会放大这一代价：一次产出多个候选意味着 token 流成倍增加，All-to-All 的消息量随候选数线性上升，而专家负载在候选间分布不均时会进一步恶化路由均衡。若 EP 组跨出 NVLink 域，All-to-All 落到跨节点链路上，其延迟量级与域内相差一个档位，解码步延迟立刻被通信主导。</p>\n<p>伪代码思路：在候选生成前先按候选数与每 token 的专家命中分布估算 All-to-All 字节量，若超过域内带宽预算则降低候选数或改走 DP 复制而非 EP。代价判断上，EP 节省的是单卡专家显存（每卡只驻留部分专家权重），付出的是每层两次 All-to-All；当解码 batch 很小、专家命中稀疏时，EP 的通信开销摊不薄，反而不如 DP 复制整模型。这与 KV cache 的分页管理是两类不同压力：EP 压的是权重显存，KV 压的是激活缓存，二者不能互相替代。</p>\n<div class=\"formula\">$$\\mathrm{bytes}_{\\mathrm{A2A}}\\approx 2\\times N_{\\mathrm{cand}}\\times T_{\\mathrm{dec}}\\times d_{\\mathrm{model}}\\times \\frac{E-1}{E}$$</div>\n<p>具体例子：验证环节回灌的失败信号若触发重新生成，会再次产生一轮 All-to-All；把验证与生成做成同步串行，等于让每一轮验证失败都额外支付一次全组通信。异步化解耦后，生成组可在等待验证结果期间继续服务其他请求的解码步，通信与验证开销被并发掩盖。</p>\n\n<h3 id=\"paper-fastcoder-accelerating-repository-le-2025-sec-34\">三十四 · PP 与 DP：流水线气泡与副本收益</h3>\n<p>PP 把层切成阶段，跨阶段只传边界激活，通信量远小于 TP 的每层 All-Reduce，但代价是流水线气泡：解码阶段每步只推进一个 token，阶段间必须串行传递，气泡占比随阶段数上升。仓库级生成的长预填反而适合 PP——预填可切分为多个 micro-batch 填充流水线，气泡被摊薄。因此同一系统在预填用 PP、解码切回 TP+DP 是合理的非对称拓扑，代价是需要两套权重布局或动态重切分，工程上通常以预填与解码分离部署（disaggregated prefill/decode）来实现，预填池与解码池各自独立切分，中间经 NIXL 搬运 KV 与请求状态。</p>\n<p>DP 是检索段与解码段扩容的首选：每副本独立处理请求，无组内通信，只增加显存与功耗。代价判断：DP 副本数受单卡显存约束（权重加 KV 分页池），在 B200 单卡容量下，代码模型的权重占比决定了可用于 KV 的余量；检索段则可用 CPU 或低档 GPU 承载，不必占用生成卡的显存。功耗维度上，DP 复制使静态功耗随副本线性上升，而 TP 扩组只增加参与同步的 SM 活跃度，空闲卡的静态功耗仍在——这是容量规划里必须计入的一项。</p>\n\n<h3 id=\"paper-fastcoder-accelerating-repository-le-2025-sec-35\">三十五 · NIXL 传输：段间搬运的隐藏延迟</h3>\n<p>NIXL 承担的是段间与节点间的点对点搬运：检索器把组装好的提示送入生成池、预填池把 KV 交给解码池、验证器把候选代码与测试产物在 GPU 与 CPU 沙箱之间往返。这些搬运不在 NVLink 全互联域内，往往经主机内存或 PCIe，单次延迟远高于域内 All-Reduce。仓库级请求的提示长度受 B_ctx 约束而非全仓库拼接，因此单次搬运量可控；但多候选与验证回灌会使搬运次数成倍增加，次数而非单次大小成为主导代价。</p>\n<p>工程判断：把前缀缓存放在生成池本地而非跨段搬运，使同仓库后续请求直接命中已检索上下文，省掉一次检索到生成的搬运；验证结果只回传通过与否的短消息与失败信号，不回传完整候选，减少反向搬运量。代价上，前缀缓存占用生成卡的显存或主机内存，需按仓库快照版本做失效校验——仓库变更后复用过期上下文会让生成引用已删除符号，这是缓存复用必须付的校验成本。</p>\n<div class=\"formula\">$$T_{\\mathrm{e2e}}=T_{\\mathrm{ret}}+T_{\\mathrm{asm}}+T_{\\mathrm{prefill}}+T_{\\mathrm{dec}}\\cdot N_{\\mathrm{cand}}+T_{\\mathrm{xfer}}\\cdot K+T_{\\mathrm{verify}}$$</div>\n<p>具体例子：一次请求若产生多个候选，解码时间按候选数线性放大，搬运次数 K 随候选与验证轮次上升，验证时间计入端到端延迟。要压住 SLO，只能让 T_verify 与 T_dec 并发重叠，并把 T_xfer 的次数压到与候选数无关——即批量搬运而非逐候选搬运。</p>\n\n<h3 id=\"paper-fastcoder-accelerating-repository-le-2025-sec-36\">三十六 · 通信何时成为瓶颈：三个判据</h3>\n<p>判据一：解码步的通信时间与计算时间之比。当 TP 组内每步 All-Reduce 的同步时延接近单层计算时间时，扩 TP 不再提速，反而因同步等待降低有效吞吐；此时应停止扩组、转向 DP 副本。判据二：EP 的 All-to-All 字节量是否超过域内带宽预算，超过则候选数或 EP 度必须下调。判据三：段间 NIXL 搬运次数是否随候选数线性增长，若是，则验证与生成的解耦不彻底，搬运成了串行瓶颈。</p>\n<p>把这三条落到容量规划上：先按解码 SLO 定 TP 组规模上限（受同步时延约束），再按并发请求数定 DP 副本数（受显存约束），最后按候选数与验证轮次定 NIXL 批量搬运的批大小。检索段独立扩容不影响生成段通信，是唯一可以近乎线性加副本的环节。通信成为瓶颈的信号很明确：GPU 利用率下降而 NVLink 或 PCIe 吞吐打满，或解码步延迟随并发上升而非随计算上升——此时应重切拓扑，而不是加卡。</p>\n<p>最终落点在一个具体机制上：预填与解码分离部署后，预填池用大 TP 或 PP 摊薄长上下文激活，解码池用小 TP 加多 DP 副本压低每步同步时延，两池之间经 NIXL 批量搬运 KV 与请求状态，验证段异步挂在解码池之后并以短消息回灌。这一拓扑把 All-Reduce、All-to-All、NIXL 三类通信各自约束在能承受的域内，代价是两套权重布局与 KV 搬运的额外显存与带宽开销，收益是解码步不再被预填的带宽需求与验证的执行时延同时挤压。</p>\n\n<h3 id=\"paper-fastcoder-accelerating-repository-le-2025-sec-37\">三十七 · 并行切分与通信：检索流水线的边界在哪里</h3>\n<p>FastCoder 的推理流水线本身不改变基座模型的解码机制，因此 TP/EP/PP/DP 的切分方式完全继承自所叠加的代码模型；真正属于该方案的是检索、组装、生成、验证四段之间的数据流。检索器与索引侧通常是 CPU 或独立服务，组装器把片段按依赖顺序拼成提示送入 GPU，生成侧一次产出多个候选，验证器再把这些候选拉回编译与测试环境。这里的通信代价不在张量并行的 All-Reduce 上，而在“检索结果→组装→多候选→验证”这条跨进程链路上：候选数量线性放大解码开销，也线性放大从生成侧到验证侧的传输量。若把候选数记为 $k$、单候选平均 token 数为 $L$，验证侧需要接收的文本量约为 $k\\cdot L$ 个 token 的序列化载荷，这与 TP 组内每层 All-Reduce 的固定通信量是两种不同性质的瓶颈。</p>\n<p>通信何时成为瓶颈，取决于三段流水线的相对耗时。设单次请求的端到端延迟为 $T=T_{\\mathrm{ret}}+T_{\\mathrm{prefill}}+T_{\\mathrm{decode}}+T_{\\mathrm{verify}}+T_{\\mathrm{xfer}}$，其中 $T_{\\mathrm{xfer}}$ 是检索片段上行与候选下行的传输时间。当 $B_{\\mathrm{ctx}}$ 被压得很小、预填与解码都很快时，$T_{\\mathrm{verify}}$ 与 $T_{\\mathrm{xfer}}$ 在总延迟中的占比上升；反之在大仓库、检索片段多的情况下，$T_{\\mathrm{ret}}$ 与上行传输先成为主导。材料未给出各段的具体数值，因此工程上只能用分段计时来定位：若验证队列等待时间随候选数 $k$ 线性增长而 GPU 利用率下降，说明瓶颈已从计算转移到验证吞吐与候选搬运，此时应减少 $k$ 或改为流式验证而非加大并行度。</p>\n<p>前缀缓存是该流水线里最容易被忽视的通信与一致性问题。通过验证的片段与结果回写前缀缓存，使同一仓库后续请求复用已检索上下文、减少重复预填与重复检索；但缓存键必须绑定仓库快照版本。若只按文件路径或函数签名做键，仓库变更后可能复用过期上下文，生成引用已删除符号——这是静默失败，验证器若测试集未覆盖该符号便无法拦截。工程判断是：缓存键至少包含仓库 commit 标识与 $B_{\\mathrm{ctx}}$ 预算档位，命中后仍需在组装阶段做一次符号存在性校验。</p>\n<table class=\"mini\"><thead><tr><th>环节</th><th>主要代价</th><th>瓶颈触发条件</th></tr></thead><tbody><tr><td>检索与上行</td><td>索引查询、片段序列化传输</td><td>仓库规模大、召回片段多</td></tr><tr><td>预填与解码</td><td>KV cache 占用、TP 组内 All-Reduce</td><td>$B_{\\mathrm{ctx}}$ 放大或候选数 $k$ 增大</td></tr><tr><td>候选下行与验证</td><td>文本传输、编译与测试执行</td><td>验证吞吐低于解码产出速率</td></tr></tbody></table>\n<p>对 Blackwell 部署而言，NVLink 5 与 NVSwitch 解决的是模型并行组内的高带宽集合通信，而检索片段与候选文本走的是主机侧或跨节点链路，二者不在同一张网上。把 TP 组做大可以降低单卡显存压力、容纳更长 $B_{\\mathrm{ctx}}$，但会抬高每层 All-Reduce 的同步开销；把 DP 副本做多可以提升并发请求吞吐，却让前缀缓存的命中率被副本间上下文不一致稀释。材料未给出并行拓扑与硬件档位，可确认的工程约束是：$B_{\\mathrm{ctx}}$ 是唯一可核验的容量参数，任何切分决策都应先固定它，再判断通信是否已成为端到端延迟的主导项，而不是反过来用并行度去掩盖检索召回不足带来的符号缺失。</p>\n<h3 id=\"paper-fastcoder-accelerating-repository-le-2025-sec-38\">三十八 · 精度塌陷：从“能跑”到“跑错”的隐性路径</h3>\n<p>在 FastCoder 这类检索增强加验证过滤的流水线里，“精度塌陷”不是指模型权重掉精度，而是指端到端一次通过率在某个负载拐点上突然下滑，而单看生成侧指标却看不出异常。塌陷的根因通常不在解码器，而在检索与组装环节的耦合失效：当仓库规模增长、请求并发上升时，组装器为了守住预算 B_ctx 会激进截断片段，跨文件定义与调用关系被切掉，模型于是生成“语法正确但符号不存在”的候选。这类候选在编译阶段才暴露，验证器把它丢弃，表现为验证通过率骤降、无效解码比例上升，而生成侧的困惑度指标几乎不变。</p>\n<p>诊断这类塌陷要盯住三个量的联合走势，而不是单点阈值。设单请求候选数为 N，验证通过数为 P，则有效候选率 r=P/N；设检索召回片段数为 k、被组装器实际保留数为 k′，则预算截断率 t=1−k′/k。塌陷的典型签名是 r 下降而 t 同步上升，且生成侧平均解码长度不降——说明模型在更短的上下文里“猜”得更长。监控上应把 r 与 t 做成同图双轴，并按仓库规模分桶；一旦某个规模桶内 r 的滑动均值跌破自身基线，就触发检索侧排查，而不是先去调生成温度。</p>\n<div class=\"formula\">$$r=\\frac{P}{N},\\qquad t=1-\\frac{k'}{k},\\qquad \\text{alarm}\\iff \\Delta r&lt;0\\ \\land\\ \\Delta t&gt;0$$</div>\n<p>具体机制上，组装器按依赖顺序拼接片段，依赖排序本身依赖索引侧的符号图；若索引在仓库快照更新后未重建，符号图的边会指向已删除的定义，组装器仍按旧顺序保留片段，模型看到的是“有调用无定义”的上下文。系统代价体现在验证环节：每个失败候选都要走一遍编译，编译是进程级重操作，N 个候选意味着 N 次编译启动开销，吞吐被验证器串行化拖住。一个可操作的例子是把目标函数所在文件的直接依赖设为“必保留集”，预算裁剪只作用于间接依赖，这样即使 B_ctx 收紧，关键符号也不会被截掉；代价是必保留集在超大文件上可能自身就逼近预算，需要在组装前先做符号级而非文件级的裁剪。</p>\n\n<h3 id=\"paper-fastcoder-accelerating-repository-le-2025-sec-39\">三十九 · OOM 与批抖动：显存账本的两条泄漏路径</h3>\n<p>OOM 在 FastCoder 部署里很少来自单请求，而来自批内请求的上下文长度方差。检索压缩把单请求预填 token 控制在 B_ctx 内，但不同请求的 B_ctx 实际占用差异很大：小仓库请求可能只用到预算的三成，大仓库请求贴着上限。连续批处理把长短请求混在一批，KV cache 按批内最长序列分配时，短请求被迫按长请求的页数占位，显存利用率被方差吃掉。设批内请求上下文长度为 L_i，批占用近似正比于 max(L_i) 乘以批大小，而非 sum(L_i)；方差越大，浪费越大。这就是“批抖动”的显存侧来源。</p>\n<p>第二条泄漏路径是前缀缓存的版本膨胀。通过验证的片段与结果回写前缀缓存，供同仓库后续请求复用；但仓库快照一旦变更，旧缓存条目若未失效，就会与新条目并存，缓存占用随快照数线性增长。缓存命中率看似健康，实际命中了很多过期条目，显存被历史版本占满，新请求反而触发 OOM。诊断上要把缓存占用按“仓库×快照版本”打标签，观察单仓库的缓存条目数是否随提交数单调上升；若是，说明失效策略缺失。</p>\n<table class=\"mini\"><thead><tr><th>症状</th><th>显存侧根因</th><th>可观测信号</th><th>处置</th></tr></thead><tbody><tr><td>批吞吐骤降但单请求延迟正常</td><td>批内长度方差导致按 max 分配</td><td>批内 L_i 方差、KV 页利用率</td><td>按长度分桶调度，长短不混批</td></tr><tr><td>缓存命中率高但 OOM 频发</td><td>多快照版本条目并存</td><td>单仓库缓存条目数随提交数上升</td><td>快照版本作缓存键，旧版本淘汰</td></tr><tr><td>预填阶段 OOM、解码阶段正常</td><td>B_ctx 贴上限且必保留集过大</td><td>组装后 token 数与 B_ctx 之比</td><td>符号级裁剪，必保留集设上限</td></tr></tbody></table>\n<p>系统代价上，分桶调度会牺牲批的填充率：短请求桶先满先发，长请求桶等待时间变长，尾延迟上升。这是一个显存与尾延迟的显式权衡，不能靠调大 batch 上限掩盖。一个具体例子是同一仓库的连续补全请求，其上下文高度重叠，若按仓库 ID 做亲和调度，让同仓库请求进同一批并共享前缀缓存页，可同时压低方差与重复预填；代价是跨仓库的批填充变差，需要在调度器里设仓库亲和的上限比例。</p>\n\n<h3 id=\"paper-fastcoder-accelerating-repository-le-2025-sec-40\">四十 · 尾延迟：验证环节是长尾的主要贡献者</h3>\n<p>FastCoder 的端到端延迟由检索、预填、解码、验证四段串成，其中验证段的分布最重尾。编译与测试的执行时间取决于候选代码触碰的依赖范围：一个只改局部表达式的候选编译很快，一个引入新 import 或改动跨文件签名的候选会拉起整条依赖链的编译。设验证耗时为 V，其分布不是单峰而是多峰，峰值位置由依赖深度决定。尾延迟的 p99 往往由少数“深依赖候选”决定，而这些候选在候选池里占比很小，均值指标完全看不出来。</p>\n<p>诊断尾延迟要把验证耗时按“候选触碰的文件数”分桶，观察每桶的 p99 是否随文件数超线性增长；若是，说明验证器没有做增量编译，每次都在全量重建。机制上可引入验证分级：先做语法与符号存在性检查（廉价、毫秒级），通过者再进编译，编译通过者再进测试。这样绝大多数失败候选在廉价层被拦下，只有少数进入重操作，尾延迟被削掉。代价是廉价层漏过的错误会进入编译层，需要保证廉价层的符号检查覆盖检索片段里的全部引用。</p>\n<div class=\"formula\">$$V_{p99}\\approx \\max_{c\\in\\text{cands}}\\big(V_{\\text{syntax}}(c)+V_{\\text{compile}}(c)+V_{\\text{test}}(c)\\big)$$</div>\n<p>系统代价还体现在 SLO 对齐上：低延迟代码补全场景要求端到端在百毫秒量级，而一次编译就可能吃掉整个预算。工程判断是把验证从同步路径挪到异步路径——先返回通过廉价检查的候选，编译与测试结果稍后回灌，失败则标记该候选为不可信并从缓存中剔除。这牺牲了“只返回通过验证的候选”的严格性，换取尾延迟可控；是否可接受取决于调用方能否容忍事后撤回。一个例子是 IDE 内联补全用异步验证，而 CI 里的批量生成用同步验证，两条路径共享同一验证器但 SLO 不同。</p>\n\n<h3 id=\"paper-fastcoder-accelerating-repository-le-2025-sec-41\">四十一 · 静默降级：验证覆盖不全与缓存过期</h3>\n<p>静默降级是 FastCoder 最危险的失败模式，因为系统所有指标都健康：验证通过率正常、延迟正常、无 OOM，但返回的代码引用了已删除的符号或漏掉了关键边界条件。两条路径导致它。第一条是验证器覆盖不全：测试集只覆盖了目标函数的常规路径，候选在未覆盖的分支上出错却通过验证。设测试覆盖率为 c，漏过率为 1−c 量级；覆盖率不提升，通过率就是虚高。第二条是前缀缓存复用过期上下文：仓库快照变更后，缓存里的检索片段仍指向旧符号，模型基于旧上下文生成，验证器在新快照上编译却因符号恰好同名而通过，错误被静默吞下。</p>\n<p>监控静默降级不能只看通过率，要看“通过但下游返工”的信号。可操作的机制是给每个缓存条目绑定仓库快照的版本号与符号指纹，复用前校验指纹；指纹不匹配则强制重新检索，代价是缓存命中率下降、重复预填增加。另一个机制是对通过验证的候选做抽样回放：定期在最新快照上重跑历史候选的编译，统计“当时通过、现在失败”的比例，这个比例就是静默降级的代理指标。系统代价是回放本身消耗编译资源，需要限流到低优先级队列。</p>\n<ul>\n<li>符号指纹：对检索片段里的每个定义取（文件路径、符号名、签名哈希）三元组，缓存键包含该集合的摘要；仓库变更导致摘要变化即失效。</li>\n<li>覆盖率看板：按目标函数的测试分支覆盖率分桶统计通过率，覆盖率低的桶通过率不作为健康信号。</li>\n<li>回放采样：按仓库维度抽样历史候选，在最新快照上重编译，统计翻转率；翻转率上升即触发缓存失效策略收紧。</li>\n</ul>\n<p>一个具体例子是重命名重构：仓库把某工具函数改名，旧缓存片段仍含旧名，模型生成的候选调用旧名，验证器在新快照上编译失败——这是显性失败，能被捕获。危险的是旧名恰好被另一个同名符号占用，编译通过但语义错位，这就是静默降级。指纹机制能拦住前者，覆盖率与回放能拦住后者。</p>\n\n<h3 id=\"paper-fastcoder-accelerating-repository-le-2025-sec-42\">四十二 · 定位与回滚：把失败模式映射到可回退的开关</h3>\n<p>定位的顺序应由信号到根因单向推进，避免在生成侧盲目调参。第一步看有效候选率 r 与预算截断率 t 的联合走势，定位检索与组装；第二步看批内长度方差与 KV 页利用率，定位调度与显存；第三步看验证耗时分桶的 p99，定位验证器；第四步看缓存条目随快照的增长与回放翻转率，定位缓存失效。每一步都对应一个可独立开关的配置项，这是回滚的前提。</p>\n<p>回滚不是回退代码版本，而是回退到上一组已知健康的配置组合。可回滚的开关至少包括：B_ctx 的取值与必保留集策略、批调度的分桶阈值与仓库亲和比例、验证分级的启用与廉价层覆盖范围、缓存键是否含快照指纹。每个开关都应有独立的灰度通道，出问题时只关一个，而不是整条流水线降级。系统代价是开关组合爆炸，需要预先定义少量“健康档位”，每档对应一组固定组合，回滚即切档。</p>\n<table class=\"mini\"><thead><tr><th>失败模式</th><th>首选定位信号</th><th>回滚开关</th><th>回滚代价</th></tr></thead><tbody><tr><td>精度塌陷</td><td>r↓ 且 t↑</td><td>放宽 B_ctx、启用必保留集</td><td>预填 token 上升、KV 占用上升</td></tr><tr><td>OOM</td><td>批内长度方差、缓存条目数</td><td>关仓库亲和、收紧缓存失效</td><td>批填充率下降、命中率下降</td></tr><tr><td>尾延迟</td><td>验证耗时分桶 p99</td><td>启用验证分级、验证异步化</td><td>严格性下降、事后撤回</td></tr><tr><td>静默降级</td><td>回放翻转率、覆盖率分桶</td><td>缓存键加指纹、强制重检索</td><td>重复预填与检索开销上升</td></tr></tbody></table>\n<p>工程判断上，回滚的触发条件应绑定业务指标而非系统指标：一次通过率与下游返工率是最终判据，显存与延迟只是约束。把回滚决策做成“业务指标跌破基线即切档”，可以避免系统指标健康而业务已受损的滞后。最后一个机制细节：切档后应保留旧档的缓存条目一段时间，避免切回时冷启动；但旧档条目必须带档位标签，防止跨档误命中——这与快照指纹是同一类校验思路，只是维度从仓库版本换成了配置档位。</p>\n<h3 id=\"paper-fastcoder-accelerating-repository-le-2025-sec-43\">四十三 · 口径先于数字：这篇论文的“可读区”与“不可读区”</h3>\n<p>FastCoder 的基准部分有一个必须先讲清楚的事实：材料没有给出数据集名称、规模、基线系统、通过率、延迟与吞吐数字，也没有给出硬件档位、并行拓扑与量化方案。这意味着任何试图从这篇论文里读出“快了多少倍”的读者都会落空。可核验的只有流程结构与一个容量约束参数 B_ctx。因此本部分的读法是：把论文当作一条<strong>可复现的流水线口径</strong>来读，而不是当作一张性能表来读。凡是涉及绝对加速比的表述，都应标注为不可比；凡是涉及结构约束（预填规模、候选数、验证执行时间）的表述，才是可讨论的工程对象。</p>\n<p>仓库级代码生成的评测口径天然分裂成三层：<em>功能正确性</em>（编译与测试通过率）、<em>端到端延迟</em>（从请求到返回可用代码）、<em>资源占用</em>（显存、带宽、功耗）。FastCoder 的验证器直接作用于第一层，却把成本记在第二层：编译与测试的执行时间计入端到端延迟。于是“通过率提升”与“延迟下降”在这条流水线上是<strong>互相拉扯</strong>的两个指标，不能合并成单一分数。读这篇论文时，任何只报通过率不报验证耗时的结果，都无法判断其在低延迟补全 SLO 下是否可用。</p>\n\n<h3 id=\"paper-fastcoder-accelerating-repository-le-2025-sec-44\">四十四 · 硬件档位与 batch/并发：材料留白处的推理系统代价</h3>\n<p>材料明确未给出 B200、B300 或 GB200 NVL72 的部署选择，也未给出批大小与并发数。这并非可以忽略的细节，而是决定了这套流水线能否落地的关键变量。检索压缩把预填 token 规模从“随仓库规模膨胀”变为“受 B_ctx 线性约束”，在 Blackwell 上的直接收益是 KV cache 占用与首 token 延迟的可预测性：预填长度受控后，tcgen05 路径上的 MMA 与 TMEM 占用不再随仓库大小抖动，分页 KV 的块数上限也可按 B_ctx 静态规划。</p>\n<p>但多候选生成会线性放大解码开销。设一次请求产出 N 个候选，单候选解码长度为 L，则解码侧的计算量近似为：</p>\n<div class=\"formula\">$$C_{\\text{decode}} \\approx N \\cdot L \\cdot C_{\\text{step}},\\qquad T_{\\text{e2e}} \\approx T_{\\text{retrieve}} + T_{\\text{prefill}}(B_{\\text{ctx}}) + N \\cdot T_{\\text{decode}}(L) + T_{\\text{verify}}$$</div>\n<p>其中 T_verify 是验证器执行编译与测试的时间，且与 N 同向增长——每个候选都要单独执行。这条式子暴露了一个调度矛盾：连续批处理擅长把多个请求的解码步拼进同一批以提高吞吐，但验证环节是<strong>外部进程</strong>，不占用 GPU 的批调度槽位，却占用墙钟时间。若把并发压到很高，GPU 侧吞吐上去了，验证队列却会成为尾延迟的瓶颈；若并发压低以保住 TPOT，则 GPU 利用率不足。材料未给出批大小，因此这个平衡点在这篇论文里是<strong>未标定的</strong>，读者只能把它当作部署时必须自己扫的参数。</p>\n<p>具体例子：同一仓库的十个补全请求并发到达，检索与组装可共享前缀缓存，预填成本被摊薄；但每个请求若产出四个候选，就有四十次编译与测试排队，验证吞吐成为端到端延迟的主导项。此时提升 GPU 侧 batch 对总延迟几乎无益，反而增加显存中同时在飞的 KV 页。</p>\n\n<h3 id=\"paper-fastcoder-accelerating-repository-le-2025-sec-45\">四十五 · 指标怎么读：TTFT、TPOT、吞吐、显存、功耗的归因链</h3>\n<p>在这条流水线上，TTFT 的构成与常规对话推理不同：它包含检索查询、索引召回、片段排序与截断、提示组装，最后才是预填。B_ctx 直接决定预填段，但检索段的时间与索引规模、召回策略相关，材料未给出索引规模，因此 TTFT 中检索占比无法量化。可确认的定性结论是：B_ctx 越小，预填段越短，TTFT 的<strong>可控部分</strong>越短，但召回不足的风险上升——这是一个用正确性换延迟的显式 trade-off，而非免费加速。</p>\n<p>TPOT 在这条流水线上被多候选结构稀释了意义：N 个候选并行或串行解码时，单请求的有效 TPOT 取决于候选是并行展开还是顺序展开，材料未说明。若候选串行解码，用户感知的 TPOT 会被放大 N 倍；若并行解码，则显存中的 KV 页数放大 N 倍，与分页 KV 的块预算冲突。吞吐指标同理：以“通过验证的候选数/秒”计与以“token/秒”计会给出完全不同的排序，前者把验证器算力计入分母，后者不计。功耗维度上，验证器的编译与测试跑在 CPU 侧，其功耗不计入 GPU 功耗曲线，因此单看 GPU 功耗会系统性低估这套流水线的真实能耗。</p>\n<table class=\"mini\"><thead><tr><th>指标</th><th>归因到</th><th>材料是否给出</th><th>读法</th></tr></thead><tbody><tr><td>TTFT</td><td>检索 + 组装 + 预填(B_ctx)</td><td>否</td><td>只可讨论预填段受 B_ctx 约束，检索段未知</td></tr><tr><td>TPOT</td><td>候选解码展开方式</td><td>否</td><td>N 候选串行/并行未说明，不可比</td></tr><tr><td>吞吐</td><td>分母是否含验证</td><td>否</td><td>token/s 与通过候选/s 不可互换</td></tr><tr><td>显存</td><td>KV 页 × N + 前缀缓存</td><td>仅 B_ctx</td><td>B_ctx 是唯一可核验容量参数</td></tr><tr><td>功耗</td><td>GPU 侧 vs CPU 验证侧</td><td>否</td><td>单看 GPU 功耗低估总能耗</td></tr></tbody></table>\n\n<h3 id=\"paper-fastcoder-accelerating-repository-le-2025-sec-46\">四十六 · 哪些提升不可比：四类典型的伪对比</h3>\n<p>第一类，<strong>上下文口径不同</strong>。把 FastCoder 与“全仓库拼接”的基线对比时，后者的预填长度随仓库规模增长，前者的预填长度被 B_ctx 截断。这种对比测的是“压缩带来的预填节省”，而不是“方法本身更聪明”；若基线也做了等预算截断，差距会大幅收窄。材料未给出基线，因此这类对比在论文中不存在，读者不应自行脑补。</p>\n<p>第二类，<strong>通过率的分母不同</strong>。以“N 个候选中至少一个通过”计的通过率，与以“单候选通过率”计的通过率，数值上不可直接比较。FastCoder 生成多候选再验证过滤，天然抬高前者；这与单候选贪心解码的基线不在同一口径上。任何声称“通过率提升”的表述，必须先问清分母是候选数还是请求数。</p>\n<p>第三类，<strong>验证成本被移出计时窗口</strong>。若某实现把编译与测试放到异步队列、在返回后才完成，则其报告的端到端延迟不含 T_verify，与同步验证的实现不可比。材料明确验证执行时间计入总延迟，这一点应作为口径基准；其他系统若不计入，其数字不能拿来对照。</p>\n<p>第四类，<strong>硬件档位与量化不同</strong>。材料未给出 B200/B300/GB200 的选择，也未给出 NVFP4/FP8 的使用。在 Blackwell 上，量化方案会同时改变预填吞吐、KV 字节数与验证前的候选质量（低精度可能降低一次通过率）。因此跨精度比较通过率是无意义的：精度变了，候选分布也变了。</p>\n\n<h3 id=\"paper-fastcoder-accelerating-repository-le-2025-sec-47\">四十七 · 前缀缓存与仓库快照：口径里最容易被忽略的变量</h3>\n<p>通过验证的片段与结果可回写前缀缓存，使同一仓库的后续请求复用已检索上下文，减少重复预填与重复检索。这在基准口径上制造了一个<strong>请求序依赖</strong>：第一个请求承担完整检索与预填，后续请求命中缓存。若评测把请求顺序打乱或跨仓库混合，缓存命中率变化会直接改变平均 TTFT，而材料未给出缓存命中率与请求序设定。因此“平均延迟”这个数字在这条流水线上高度依赖负载构造方式，不可跨实验直接比较。</p>\n<p>更隐蔽的是快照版本问题。前缀缓存复用检索片段时若未校验仓库快照版本，仓库变更后可能复用过期上下文，生成引用已删除符号。这类失败不会体现在通过率上——它表现为编译失败或测试失败，被验证器丢弃，从而<strong>伪装成一次正常的候选淘汰</strong>。于是缓存带来的延迟收益与验证器承担的额外淘汰率纠缠在一起：缓存越激进，验证器丢弃的过期候选越多，T_verify 的有效负载越大。基准设计若不做快照失效注入，就测不出这条路径的代价。</p>\n<p>工程判断：把 B_ctx 当作固定常量是这类流水线最常见的口径错误。小仓库上它浪费预算、拉长预填；大仓库上它丢失关键符号、抬高验证淘汰率。合理做法是让 B_ctx 随仓库规模与请求类型（补全 vs 函数级生成）分档，并把召回率、验证通过率、验证平均执行耗时三项作为与延迟并列的监控指标——材料未给出阈值，但这三项是唯一能把“加速”与“静默失败”区分开的观测面。</p>\n\n<h3 id=\"paper-fastcoder-accelerating-repository-le-2025-sec-48\">四十八 · 落到可执行的读法：把论文当口径模板而非成绩单</h3>\n<p>对工程读者而言，这篇论文在基准维度上的可用产出不是数字，而是一张<strong>必须补齐的口径清单</strong>：硬件档位（B200/B300/GB200 NVL72 与互联拓扑）、量化方案（NVFP4/FP8 对候选质量的影响）、batch 与并发、N 与 L 的取值、验证器覆盖率与平均执行耗时、缓存命中率与请求序、B_ctx 的取值策略。缺任何一项，跨系统比较都不成立。反过来，若要在自己的 Blackwell 部署上复现这套流水线，应先固定 B_ctx 与 N，测出 T_prefill(B_ctx) 与 T_verify 的比值；当 T_verify 超过 T_prefill 时，瓶颈已从 GPU 转移到验证侧，此时继续压缩上下文或加大 batch 都是错方向，应改为提高验证并行度或收紧候选数。</p>\n<p>最后一个具体机制层面的判断：验证器是这条流水线里唯一不被 GPU 批调度覆盖的阶段，也是唯一能把“概率排序”替换为“执行事实”的阶段。它的吞吐决定了 N 的上界，而 N 又反过来决定解码开销与 KV 页数。因此这套系统的容量规划应以<strong>验证吞吐</strong>为锚点反推 GPU 侧配置，而不是以 GPU 吞吐为锚点去堆候选——材料未给出这条曲线的任何数字，但结构上这个反推关系是确定的。</p>\n\n<h3 id=\"paper-fastcoder-accelerating-repository-le-2025-sec-49\">四十九 · 基准口径与不可比边界：把 B_ctx、候选数与验证耗时放进同一张账</h3>\n\n<p>读这套流水线的任何数字，先要把它拆成四个可独立变动的旋钮：上下文预算 B_ctx、单请求候选数 N、验证器单候选执行耗时 T_v、以及并发批大小。端到端延迟的骨架可以写成 <span class=\"formula\">$$T_{\\text{e2e}} \\approx T_{\\text{retrieval}} + T_{\\text{prefill}}(B_{\\mathrm{ctx}}) + N\\cdot T_{\\text{decode}} + N\\cdot T_v$$</span>，其中只有第二项随 B_ctx 线性受控，第三、四项随 N 线性放大。这意味着“检索压缩降低预填”与“多候选验证抬高尾延迟”是同一笔预算的两端：把 B_ctx 压小换来 TTFT 下降，却可能因召回不足使 N 被迫增大以维持一次通过率，TPOT 与验证段反而吃掉收益。任何只报 TTFT 改善、不报 N 与 T_v 的结果，都无法判断加速来自上下文压缩还是候选筛选策略的改变。</p>\n\n<p>硬件档位与量化口径是第二层不可比来源。材料明确未给出 B200/B300/GB200 NVL72 的部署选择、并行拓扑与量化方案，因此同一 B_ctx 在 FP8 与 NVFP4 下的 KV cache 占用与预填吞吐完全不同——前者决定单卡能挂多少并发会话，后者决定 TTFT 的斜率。工程上应把口径钉死为三元组（精度、B_ctx、并发），否则跨系统比较等于拿不同显存预算下的吞吐互比。功耗维度同理：验证器是 CPU 侧编译与测试负载，其能耗不进 GPU 功耗读数，却实打实计入端到端延迟与机房总功耗，只报 GPU 侧指标的基准会系统性低估该方案的成本。</p>\n\n<table class=\"mini\"><thead><tr><th>口径项</th><th>材料给定</th><th>可比性判断</th></tr></thead><tbody><tr><td>上下文预算 B_ctx</td><td>唯一可核验容量约束，数值未给出</td><td>必须与仓库规模、请求类型绑定后才可比</td></tr><tr><td>候选数 N / 解码长度</td><td>未给出</td><td>N 不同则 TPOT 与验证负载不可比</td></tr><tr><td>验证覆盖率与 T_v</td><td>未给出</td><td>测试集构造不同则通过率不可比</td></tr><tr><td>硬件档位 / 量化</td><td>未给出</td><td>精度不同则显存与吞吐不可比</td></tr></tbody></table>\n\n<p>第三层是缓存复用带来的口径漂移。通过验证的片段回写前缀缓存后，同仓库后续请求的 T_prefill 被摊薄，基准若混测冷启动与热缓存请求，得到的平均 TTFT 既不代表首请求也不代表稳态。更隐蔽的失效条件是仓库快照版本未校验：仓库变更后复用过期上下文，生成会引用已删除符号，这类错误往往能通过编译却在测试中静默漏过，表现为“通过率虚高而返工率上升”。因此基准必须分别报告冷/热两条曲线，并把验证通过率与下游返工率并列，单看通过率会把验证器覆盖不全的漏洞读成质量提升。</p>\n<h3 id=\"paper-fastcoder-accelerating-repository-le-2025-sec-50\">五十 · 迁移到非代码领域：检索器的语义退化与验证器的消失</h3>\n<p>FastCoder 的三段式结构（检索—生成—验证）在代码域成立的前提有两个：一是仓库索引的键是符号与调用关系这类结构化对象，二是验证器有编译器和测试套件这种确定性裁判。迁到自然语言领域，这两个前提同时松动。检索器从“符号级召回”退化为“段落级语义相似度”，<code>score(q, d_i)</code> 不再能保证召回的是定义而非提及；验证器则没有编译等价物，只能退回到模型自评或人工抽检，而模型自评的判别力远低于编译器报错。工程上的直接后果是：验证环节从“确定性过滤”变成“概率性过滤”，漏过率上升，静默失败取代编译失败成为主要失败模式。迁移时应当保留的不是验证环节的形式，而是它的位置——在候选返回前插入一个外部裁判，哪怕这个裁判是单元测试生成器或规则检查器，也比让模型自评强。代价上，验证执行时间从毫秒级编译变为秒级模型调用，端到端延迟结构改变，低延迟 SLO 不再成立。</p>\n<p>具体例子：把同一流水线用于 API 文档生成，检索召回的是函数签名段落，验证器只能检查生成文本是否包含签名中的参数名——这是字符串匹配而非语义验证，覆盖不全时错误候选直接漏过。此时应把 B_ctx 的预算逻辑保留，把验证逻辑替换为可执行的 schema 校验，而不是照搬编译验证。</p>\n\n<h3 id=\"paper-fastcoder-accelerating-repository-le-2025-sec-51\">五十一 · 迁到别的代码模型：解码机制不变，但候选数与验证吞吐的匹配要重算</h3>\n<p>该方法不改变基座模型的解码机制，因此叠加到任意代码模型上在接口层面是可行的：检索与验证都是外部环节，模型只看到组装后的提示。但迁移时必须重算两个耦合参数。其一是候选数 N 与验证吞吐的匹配：多候选线性放大解码开销，而验证器的执行是串行或受限并行的，若 N 增大而验证并发不变，端到端延迟由验证环节主导而非解码主导。其二是 B_ctx 与模型有效上下文窗口的关系：小窗口模型上 B_ctx 被压得更紧，检索召回不足的代价被放大；大窗口模型上 B_ctx 可以放宽，但预填成本随预算线性上升，KV cache 占用随之膨胀。迁移判断是：候选数应设为验证并发与单次验证耗时的函数，而非固定值。</p>\n<div class=\"formula\">$$T_{\\text{e2e}} \\approx T_{\\text{retrieve}} + T_{\\text{prefill}}(B_{\\text{ctx}}) + N \\cdot T_{\\text{decode}} + \\left\\lceil N / C_{\\text{verify}} \\right\\rceil \\cdot T_{\\text{verify}}$$</div>\n<p>其中 <code>C_verify</code> 是验证并发度。这个式子说明：当 <code>T_verify</code> 远大于 <code>T_decode</code> 时，增大 N 只增加解码开销而不改善端到端延迟，因为验证批次成为瓶颈。迁移到量化后的模型时，解码变快而验证耗时不变，瓶颈进一步向验证侧偏移，此时应减少 N 而非增加。具体例子：同一仓库请求在未量化模型上 N=4 时解码与验证大致平衡，换到低精度解码后解码时间下降，若不调整 N，验证环节占比上升，SLO 被拖垮。</p>\n\n<h3 id=\"paper-fastcoder-accelerating-repository-le-2025-sec-52\">五十二 · 与 Blackwell 部署机制的衔接：前缀缓存是唯一可直接复用的杠杆</h3>\n<p>材料明确未给出硬件档位、并行拓扑与量化方案，因此不能声称该方法在 B200 或 GB200 NVL72 上有特定收益。可判断的是衔接点：检索压缩上下文直接约束预填 token 规模，这与 Blackwell 上 KV cache 容量和预填带宽的约束方向一致；通过验证的片段回写前缀缓存，使同仓库后续请求复用已检索上下文，这是与分页 KV、前缀复用机制天然对齐的一环。真正需要改的是缓存失效策略——仓库快照变更后，前缀缓存中的检索片段可能引用已删除符号，必须把仓库版本号纳入缓存键，否则复用过期上下文会生成不可编译代码。这是迁移到任何支持前缀缓存的推理栈时都必须补的一课，与硬件无关。</p>\n<p>代价判断：前缀缓存复用降低重复预填，但缓存本身占用显存，仓库级请求的缓存条目多且片段长，缓存命中率与显存预算之间存在取舍。在显存受限的部署档位上，应优先缓存高频仓库的检索片段而非全部，用命中率换容量。</p>\n\n<h3 id=\"paper-fastcoder-accelerating-repository-le-2025-sec-53\">五十三 · 规模上限：检索质量与验证覆盖率决定天花板，而非上下文预算</h3>\n<p>该方法的规模上限不在 B_ctx，而在两个外部环节的质量。检索侧：仓库越大，符号越多，固定预算下召回率下降，跨文件定义与调用关系越容易丢失；当仓库规模超过索引可维护的范围，检索退化为近似随机采样，生成缺少关键符号。验证侧：测试覆盖率随仓库增大而稀释，验证器覆盖不全时错误候选漏过，形成静默失败。因此规模上限的工程判断是：当仓库规模增长到检索召回率无法维持、或验证覆盖率无法覆盖改动路径时，应停止扩大单次请求的仓库范围，改为按模块切分请求，用多次受控请求替代一次全仓库请求。</p>\n<ul>\n<li>检索上限：索引规模与召回阈值未给出，无法量化；判断依据是召回片段的符号完整率，而非相似度分数。</li>\n<li>验证上限：测试集构造方式未给出；判断依据是改动路径是否被测试覆盖，未覆盖路径上的候选应降级为人工复核而非直接返回。</li>\n<li>预算上限：B_ctx 作为固定常量在小仓库浪费预算、在大仓库丢失符号，应按仓库规模与请求类型动态调整。</li>\n</ul>\n<p>具体例子：单仓库请求在模块切分后，每次请求的 B_ctx 只需覆盖目标模块及其直接依赖，预填规模下降，检索召回率上升，验证范围也收敛到该模块的测试集——这是用请求切分换质量，代价是跨模块调用的上下文需要额外拼接。</p>\n\n<h3 id=\"paper-fastcoder-accelerating-repository-le-2025-sec-54\">五十四 · 不适用的场景与判断边界</h3>\n<p>三类场景应明确不适用。第一类是低延迟补全：验证执行时间计入端到端延迟，编译与测试的开销与补全 SLO 存在结构性张力，材料未给出延迟数字但机制上无法回避；此类场景应只保留检索压缩，去掉验证过滤，或把验证移到异步侧。第二类是仓库快照高频变更的场景：前缀缓存复用过期上下文的风险高于收益，缓存失效逻辑的成本可能超过预填节省。第三类是无测试套件的仓库：验证器退化为仅编译，覆盖不全导致静默失败率上升，此时验证环节的筛选价值低于其延迟代价。</p>\n<p>判断边界可以归纳为一条：验证环节的价值等于“漏过率下降带来的下游返工节省”减去“验证执行延迟”。当仓库有高覆盖率测试且下游返工成本高时，验证值得保留；当测试覆盖低或 SLO 严格时，应把验证降级为异步或抽样。这条判断不依赖硬件档位，也不依赖模型规模，是迁移时最应优先核验的一项。</p>\n<p>迁移到新领域或新模型时，先核验三件事：检索键是否仍是结构化符号、验证器是否有确定性裁判、仓库快照版本是否进入缓存键。三者任一不成立，流水线的加速逻辑就从“压缩上下文加过滤候选”退化为“压缩上下文加概率筛选”，收益结构改变，需要重新做容量规划而非照搬参数。</p>\n\n<h3 id=\"paper-fastcoder-accelerating-repository-le-2025-sec-55\">五十五 · 迁移与边界：检索-验证流水线的适用条件与失效面</h3>\n\n<p>这套方案的可迁移性来自一个结构性事实：它不触碰基座模型的解码机制，检索器、组装器、验证器都是模型外部环节，因此换模型、换语言、换仓库形态时，改动集中在外部三件套而非解码内核。但“能叠加”不等于“能等价加速”。迁移时要改的第一处是检索器的符号表示：代码检索的有效性依赖签名、调用关系与文件路径这类结构化信号，换成自然语言语料或跨语言仓库时，索引侧必须重建，召回质量随之重新标定。第二处是组装器的预算策略：<span class=\"formula\">$$\\mathrm{ctx}=\\mathrm{TopK}\\big(\\mathrm{score}(q,\\,d_i)\\big),\\quad |\\mathrm{ctx}|\\le B_{\\mathrm{ctx}}$$</span> 中 B_ctx 若被当作固定常量，小仓库会浪费预填预算、大仓库会截掉关键符号；迁移到仓库规模分布不同的场景，B_ctx 必须随请求类型与仓库规模自适应，否则检索压缩的收益直接反转为召回损失。第三处是验证器：编译与测试的可执行性依赖语言工具链与测试环境，迁到无成熟构建系统或测试覆盖稀疏的领域，验证器退化为语法检查，筛选能力大幅缩水。系统代价上，多候选生成会线性放大解码开销，候选数与验证吞吐必须匹配，否则验证队列成为端到端延迟的瓶颈；前缀缓存回写虽能摊薄同仓库重复预填，但仓库快照版本未校验时会复用过期上下文，生成引用已删除符号，这是迁移到高频变更仓库时最典型的静默失效。</p>\n\n<p>不适用边界可以按三个维度划。其一是延迟敏感度：低延迟代码补全的 SLO 以毫秒计，而验证环节的编译与测试执行时间计入端到端延迟，验证覆盖率越高、执行越重，SLO 越难对齐；在这类场景里，验证过滤应降级为异步或抽样，而不是串在关键路径上。其二是召回可保证性：当目标函数的跨文件依赖密集且符号命名不规范时，检索召回不足会丢失定义与调用关系，模型缺少关键符号，一次通过率不升反降；此时应回退到更大预算或分层检索，而不是继续压缩。其三是验证可判定性：测试集构造不全时错误候选漏过形成静默失败，通过率指标失真，系统会把“验证通过”误当作“正确”，这类漏过率材料未给出，部署时必须自行埋点。规模上限同样来自这三处：B_ctx 约束了单次预填的 KV cache 占用，仓库索引规模决定检索延迟，验证吞吐决定候选数的实际上限；三者中任一成为瓶颈，整体吞吐就不再随硬件线性扩展。迁到 Blackwell 档位时，量化与并行拓扑材料未给出，可确认的只是预算参数 B_ctx 是唯一可核验的容量约束，其余需实测标定。</p>\n\n<table class=\"mini\"><thead><tr><th>迁移维度</th><th>需改动环节</th><th>失效条件</th><th>系统代价</th></tr></thead><tbody><tr><td>换模型/换语言</td><td>检索器符号表示与索引重建</td><td>结构化信号缺失，召回不可标定</td><td>检索延迟与索引存储上升</td></tr><tr><td>换仓库规模</td><td>B_ctx 自适应策略</td><td>固定预算截断关键符号</td><td>预填与 KV cache 失控或召回损失</td></tr><tr><td>低延迟补全</td><td>验证器移出关键路径</td><td>编译测试耗时拖垮 SLO</td><td>端到端延迟被验证队列主导</td></tr><tr><td>高频变更仓库</td><td>前缀缓存版本校验</td><td>复用过期上下文引用已删符号</td><td>静默失败与返工成本</td></tr></tbody></table>\n\n<p>工程判断应落在“验证是否值得串行”这一条上：当验证执行耗时远小于一次无效解码加下游返工的成本时，串行验证过滤是净收益；当验证耗时接近或超过生成耗时，尤其在多候选线性放大解码开销的情况下，正确做法是把验证改为候选排序信号而非硬门槛，或只对高置信候选执行完整测试。迁移到新领域前，先测三个量——检索召回率、验证平均执行耗时、验证漏过率——三者任一不可测，这套流水线的加速声明就不可信；B_ctx 与候选数则应作为联合调参对象，而不是各自独立的常量。</p>\n<figure class=\"diagram\" data-fig=\"paper-family\"><svg style=\"max-width:746px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 746.0 138\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><text x=\"136.0\" y=\"32.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"10.5\" fill=\"#68727d\" font-weight=\"600\" text-anchor=\"middle\">上游 · 站在谁肩上</text><rect x=\"38.0\" y=\"44.0\" width=\"196.0\" height=\"35.0\" rx=\"6\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><text x=\"48.0\" y=\"61.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"12.0\" fill=\"#b45309\" font-weight=\"500\" text-anchor=\"start\">领域入口（无上游）</text><text x=\"380.0\" y=\"32.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"10.5\" fill=\"#68727d\" font-weight=\"600\" text-anchor=\"middle\">本文</text><rect x=\"282.0\" y=\"44.0\" width=\"196.0\" height=\"52.0\" rx=\"6\" fill=\"#e9eff5\" stroke=\"#d6e2ec\" stroke-width=\"1.2\"/><text x=\"292.0\" y=\"61.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"12.0\" fill=\"#163a5a\" font-weight=\"500\" text-anchor=\"start\">FastCoder: Accelerating </text><text x=\"292.0\" y=\"78.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"12.0\" fill=\"#163a5a\" font-weight=\"500\" text-anchor=\"start\">Repository-leve…</text><text x=\"624.0\" y=\"32.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"10.5\" fill=\"#68727d\" font-weight=\"600\" text-anchor=\"middle\">下游 · 被谁接走</text><rect x=\"526.0\" y=\"44.0\" width=\"196.0\" height=\"35.0\" rx=\"6\" fill=\"#e8f5ec\" stroke=\"#cde9d5\" stroke-width=\"1.2\"/><text x=\"536.0\" y=\"61.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"12.0\" fill=\"#15803d\" font-weight=\"500\" text-anchor=\"start\">暂无下游记录</text><line x1=\"238.0\" y1=\"74.0\" x2=\"271.0\" y2=\"74.0\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 270.0 69.5 L 270.0 78.5 L 278.0 74.0 Z\" fill=\"#d8d3c6\"/><line x1=\"482.0\" y1=\"74.0\" x2=\"515.0\" y2=\"74.0\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 514.0 69.5 L 514.0 78.5 L 522.0 74.0 Z\" fill=\"#d8d3c6\"/><text x=\"380.0\" y=\"128.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.0\" fill=\"#68727d\" font-weight=\"400\" text-anchor=\"middle\">2025 · arXiv preprint</text></svg><figcaption><b>家谱</b> · FastCoder: Accelerating… 的上游问题、本文位置与下游继承；箭头表示方法/问题的传递，不是时间先后。</figcaption></figure>\n<table class=\"mini\" data-fig=\"paper-exp\"><caption>实验速查：这篇论文拿什么数据、和谁比、提升来自哪里</caption><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td>数据集</td><td>仓库级代码生成基准（材料未给出具体数据集名称与规模）</td></tr><tr><td>基线</td><td>未给出具体基线系统名称</td></tr><tr><td>主要结果</td><td>材料未给出可核验的通过率、延迟或吞吐数字；可确认的是方法以检索压缩上下文并…</td></tr><tr><td>消融</td><td>材料未给出消融实验设置与数字；无法核验检索模块与验证模块各自的贡献比例，相…</td></tr><tr><td>局限</td><td>材料未给出失败模式统计与消融规模；可推断的风险包括检索召回不足导致关键符号…</td></tr></tbody></table>\n<p class=\"paper-line\">本页对应：papers/paper-fastcoder-accelerating-repository-le-2025 · 共 9 个片段</p>\n";break;}}})();
